src/backend.rs:
//! A jj commit backend whose objects are amber objects.
//!
//! Files, trees and commits are stored in a local core-rs packstore under the repo's store directory
//! (`.jj/repo/store/amber/packstore`), and every jj id is the 32-byte amber key of its object:
//!
//! | jj | amber |
//! | --- | --- |
//! | `FileId` | the file's root key (`Blob` or `FileNode`), chunked as `ingest` chunks |
//! | `SymlinkId` | the key of a `Blob` holding the target; trees keep the target inline |
//! | `TreeId` | a `DirLeaf` or `DirNode` key |
//! | `CommitId` | a `Commit` key |
//!
//! Because the ids are amber keys, a jj commit written here is the same object a dstore reference can
//! name: pushing a bookmark is uploading the commit's closure and putting a reference on its key
//! ([`crate::dstore`]). The mapping of the commit record is in [`crate::convert`].

use std::convert::Infallible;
use std::fmt;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::Arc;
use std::time::SystemTime;

use amber_store_core::chunkers::{ItemChunker, split_bytes};
use amber_store_core::commit::Commit as AmberCommit;
use amber_store_core::fstree::{self, DirBuilder, Entry, IndexBuilder, Object};
use amber_store_core::key::{Key, Type};
use amber_store_core::packstore;
use async_trait::async_trait;
use futures::io::Cursor;
use futures::stream::BoxStream;
use futures::{AsyncRead, AsyncReadExt as _, StreamExt as _};
use jj_lib::backend::{
    Backend, BackendError, BackendInitError, BackendLoadError, BackendResult, ChangeId, Commit, CommitId,
    CopyHistory, CopyId, CopyRecord, FileId, RelatedCopy, SigningFn, SymlinkId, Tree, TreeId, TreeValue,
    make_root_commit,
};
use jj_lib::index::Index;
use jj_lib::object_id::ObjectId as _;
use jj_lib::repo_path::{RepoPath, RepoPathBuf, RepoPathComponentBuf};
use jj_lib::settings::UserSettings;

use crate::convert;

/// The name recorded in `.jj/repo/store/type`.
pub const BACKEND_NAME: &str = "amber";

/// Every id is an amber key.
pub const COMMIT_ID_LENGTH: usize = amber_store_core::key::SIZE;
/// jj's customary change-id length; amber stores it opaquely (key 7).
pub const CHANGE_ID_LENGTH: usize = 16;

/// Item chunker bits for file and directory indexes: `ingest`'s default, so a file stored here has
/// the key `amber-store ingest` gives the same bytes.
const ITEM_BITS: u32 = 7;

/// Small segments: every jj command is a process that opens the store, and opening costs about
/// 0.1 us per record in the active segments (core `CLAUDE.md`, "opening a store").
const SEGMENT_SIZE: u64 = 64 << 20;

const MODE_TYPE: u64 = 0o170000;
const S_IFREG: u64 = 0o100000;
const S_IFDIR: u64 = 0o040000;
const S_IFLNK: u64 = 0o120000;
const MODE_FILE: u64 = 0o100644;
const MODE_EXEC: u64 = 0o100755;
const MODE_DIR: u64 = 0o040755;
const MODE_LINK: u64 = 0o120777;

/// The key of the empty directory: a `DirLeaf` whose body is the empty CBOR array.
pub fn empty_dir_key() -> Key {
    Key::new(Type::DirLeaf, 1, &[0x80])
}

pub struct AmberBackend {
    path: PathBuf,
    store: Arc<packstore::Store>,
    root_commit_id: CommitId,
    root_change_id: ChangeId,
    empty_tree_id: TreeId,
}

impl fmt::Debug for AmberBackend {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("AmberBackend").field("path", &self.path).finish_non_exhaustive()
    }
}

impl AmberBackend {
    /// The directory under jj's store directory that holds the packstore and the remote list.
    pub fn amber_dir(store_path: &Path) -> PathBuf {
        store_path.join("amber")
    }

    pub fn init(_settings: &UserSettings, store_path: &Path) -> Result<Self, BackendInitError> {
        let backend = Self::open(store_path).map_err(|e| BackendInitError(e.into()))?;
        let empty = fstree::encode_dir_leaf(&[]).map_err(|e| BackendInitError(e.into()))?;
        debug_assert_eq!(empty.key, empty_dir_key());
        backend.store.put(empty.key, &empty.bytes).map_err(|e| BackendInitError(e.into()))?;
        Ok(backend)
    }

    pub fn load(_settings: &UserSettings, store_path: &Path) -> Result<Self, BackendLoadError> {
        Self::open(store_path).map_err(|e| BackendLoadError(e.into()))
    }

    fn open(store_path: &Path) -> Result<Self, packstore::Error> {
        let path = Self::amber_dir(store_path);
        let store = packstore::Store::open_with(
            path.join("packstore"),
            packstore::Options::new().sync(true).segment_size(SEGMENT_SIZE),
        )?;
        Ok(Self {
            path,
            store: Arc::new(store),
            root_commit_id: CommitId::new(vec![0; COMMIT_ID_LENGTH]),
            root_change_id: ChangeId::new(vec![0; CHANGE_ID_LENGTH]),
            empty_tree_id: TreeId::new(empty_dir_key().as_bytes().to_vec()),
        })
    }

    /// `.jj/repo/store/amber`.
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// The local packstore, shared with the dstore transfers.
    pub fn store(&self) -> &Arc<packstore::Store> {
        &self.store
    }

    /// The amber key a commit id stands for; the root commit has none.
    pub fn commit_key(&self, id: &CommitId) -> BackendResult<Option<Key>> {
        if *id == self.root_commit_id {
            return Ok(None);
        }
        typed_key(id.as_bytes(), &[Type::Commit], "commit").map(Some)
    }

    fn get(&self, k: Key, object_type: &str) -> BackendResult<Vec<u8>> {
        self.store.get(k).map_err(|e| {
            if e.is_not_found() {
                BackendError::ObjectNotFound {
                    object_type: object_type.to_owned(),
                    hash: k.to_string(),
                    source: Box::new(e),
                }
            } else {
                BackendError::ReadObject {
                    object_type: object_type.to_owned(),
                    hash: k.to_string(),
                    source: Box::new(e),
                }
            }
        })
    }

    fn put_all(&self, objects: Vec<Object>, object_type: &'static str) -> BackendResult<()> {
        self.store
            .write_batch(objects.into_iter().map(|o| Ok::<_, Infallible>(packstore::Object::from(o))))
            .map_err(|e| BackendError::WriteObject { object_type, source: Box::new(e) })
    }

    /// Stores `data` as a file and returns its root key: one `Blob` per chunk under a `FileNode`
    /// index, or the single `Blob` itself, as `ingest` builds files. The empty file is the empty Blob.
    pub fn write_file_bytes(&self, data: &[u8]) -> BackendResult<Key> {
        let (root, objects) = build_file(data)?;
        self.put_all(objects, "file")?;
        Ok(root)
    }

    pub fn read_file_bytes(&self, k: Key) -> BackendResult<Vec<u8>> {
        let mut out = Vec::new();
        fstree::write_content(&mut out, k, |kk| self.store.get(kk)).map_err(|e| {
            BackendError::ReadObject { object_type: "file".into(), hash: k.to_string(), source: Box::new(e) }
        })?;
        Ok(out)
    }

    fn tree_value_to_entry(&self, name: &str, value: &TreeValue) -> BackendResult<Entry> {
        let mut e = Entry { name: name.as_bytes().to_vec(), ..Default::default() };
        match value {
            TreeValue::File { id, executable, copy_id: _ } => {
                typed_key(id.as_bytes(), &[Type::Blob, Type::FileNode], "file")?;
                e.mode = if *executable { MODE_EXEC } else { MODE_FILE };
                e.content_key = id.to_bytes();
            }
            TreeValue::Symlink(id) => {
                let k = typed_key(id.as_bytes(), &[Type::Blob], "symlink")?;
                e.mode = MODE_LINK;
                e.link_target = self.get(k, "symlink")?;
            }
            TreeValue::Tree(id) => {
                typed_key(id.as_bytes(), &[Type::DirLeaf, Type::DirNode], "tree")?;
                e.mode = MODE_DIR;
                e.content_key = id.to_bytes();
            }
            TreeValue::GitSubmodule(id) => {
                // A directory entry may hold a commit and reads as its tree (core
                // architecture/commits.md, "Commits inside directories").
                let Some(k) = self.commit_key(id)? else {
                    return Err(BackendError::Unsupported(format!(
                        "{name}: a submodule cannot point at the root commit"
                    )));
                };
                e.mode = MODE_DIR;
                e.content_key = k.as_bytes().to_vec();
            }
        }
        Ok(e)
    }

    /// Maps one directory entry to a jj tree value. Entries jj cannot represent (devices, fifos,
    /// sockets, which a tree ingested from a filesystem may hold) map to `None` and are left out.
    fn entry_to_tree_value(&self, e: &Entry, extra: &mut Vec<Object>) -> BackendResult<Option<TreeValue>> {
        let value = match e.mode & MODE_TYPE {
            S_IFREG => {
                let id = if e.content_key.is_empty() {
                    // Not written by core's ingest, which always stores the empty Blob; accept it.
                    let empty = fstree::encode_blob(&[]);
                    let k = empty.key;
                    extra.push(empty);
                    k.as_bytes().to_vec()
                } else {
                    e.content_key.clone()
                };
                TreeValue::File {
                    id: FileId::new(id),
                    executable: e.mode & 0o100 != 0,
                    copy_id: CopyId::placeholder(),
                }
            }
            S_IFDIR => {
                let k = Key::parse(&e.content_key).map_err(|err| BackendError::ReadObject {
                    object_type: "tree".into(),
                    hash: hex::encode(&e.content_key),
                    source: Box::new(err),
                })?;
                if k.type_() == Type::Commit {
                    TreeValue::GitSubmodule(CommitId::new(e.content_key.clone()))
                } else {
                    TreeValue::Tree(TreeId::new(e.content_key.clone()))
                }
            }
            S_IFLNK => {
                // The target lives in the entry; its SymlinkId is the key of a Blob of the target,
                // which is stored so that read_symlink finds it.
                let blob = fstree::encode_blob(&e.link_target);
                let id = SymlinkId::new(blob.key.as_bytes().to_vec());
                extra.push(blob);
                TreeValue::Symlink(id)
            }
            _ => return Ok(None),
        };
        Ok(Some(value))
    }
}

/// Parses a 32-byte id as a canonical amber key of one of the given types.
fn typed_key(bytes: &[u8], types: &[Type], object_type: &str) -> BackendResult<Key> {
    if bytes.len() != COMMIT_ID_LENGTH {
        return Err(BackendError::InvalidHashLength {
            expected: COMMIT_ID_LENGTH,
            actual: bytes.len(),
            object_type: object_type.to_owned(),
            hash: hex::encode(bytes),
        });
    }
    let k = Key::parse(bytes).map_err(|e| BackendError::ReadObject {
        object_type: object_type.to_owned(),
        hash: hex::encode(bytes),
        source: Box::new(e),
    })?;
    if !types.contains(&k.type_()) {
        return Err(BackendError::ReadObject {
            object_type: object_type.to_owned(),
            hash: k.to_string(),
            source: format!("key of type {} where {object_type} was expected", k.type_()).into(),
        });
    }
    Ok(k)
}

fn build_file(data: &[u8]) -> BackendResult<(Key, Vec<Object>)> {
    let to_err = |e: String| BackendError::WriteObject { object_type: "file", source: e.into() };
    let mut objects = Vec::new();
    let mut ib = IndexBuilder::new_file(ItemChunker::new(ITEM_BITS));
    let mut chunks = Vec::new();
    split_bytes(data, None, |chunk: Vec<u8>| -> Result<(), Infallible> {
        chunks.push(chunk);
        Ok(())
    })
    .map_err(|e| to_err(format!("{e:?}")))?;
    if chunks.is_empty() {
        chunks.push(Vec::new());
    }
    let mut emit = |o: Object| -> Result<(), Infallible> {
        objects.push(o);
        Ok(())
    };
    for chunk in chunks {
        let blob = fstree::encode_blob(&chunk);
        let k = blob.key;
        emit(blob).unwrap();
        ib.add_child(&mut emit, k, &[]).map_err(|e| to_err(format!("{e:?}")))?;
    }
    let root = ib.finish(&mut emit).map_err(|e| to_err(format!("{e:?}")))?;
    Ok((root, objects))
}

fn to_other(e: impl Into<Box<dyn std::error::Error + Send + Sync>>) -> BackendError {
    BackendError::Other(e.into())
}

#[async_trait]
impl Backend for AmberBackend {
    fn name(&self) -> &str {
        BACKEND_NAME
    }

    fn commit_id_length(&self) -> usize {
        COMMIT_ID_LENGTH
    }

    fn change_id_length(&self) -> usize {
        CHANGE_ID_LENGTH
    }

    fn root_commit_id(&self) -> &CommitId {
        &self.root_commit_id
    }

    fn root_change_id(&self) -> &ChangeId {
        &self.root_change_id
    }

    fn empty_tree_id(&self) -> &TreeId {
        &self.empty_tree_id
    }

    fn concurrency(&self) -> usize {
        1
    }

    async fn read_file(
        &self,
        _path: &RepoPath,
        id: &FileId,
    ) -> BackendResult<Pin<Box<dyn AsyncRead + Send>>> {
        let k = typed_key(id.as_bytes(), &[Type::Blob, Type::FileNode], "file")?;
        let data = self.read_file_bytes(k)?;
        Ok(Box::pin(Cursor::new(data)))
    }

    async fn write_file(
        &self,
        _path: &RepoPath,
        contents: &mut (dyn AsyncRead + Send + Unpin),
    ) -> BackendResult<FileId> {
        let mut data = Vec::new();
        contents.read_to_end(&mut data).await.map_err(to_other)?;
        let k = self.write_file_bytes(&data)?;
        Ok(FileId::new(k.as_bytes().to_vec()))
    }

    async fn read_symlink(&self, _path: &RepoPath, id: &SymlinkId) -> BackendResult<String> {
        let k = typed_key(id.as_bytes(), &[Type::Blob], "symlink")?;
        let target = self.get(k, "symlink")?;
        String::from_utf8(target).map_err(|e| BackendError::InvalidUtf8 {
            object_type: "symlink".into(),
            hash: k.to_string(),
            source: e.utf8_error(),
        })
    }

    async fn write_symlink(&self, _path: &RepoPath, target: &str) -> BackendResult<SymlinkId> {
        if target.is_empty() {
            // A directory entry's empty link target is the absent one.
            return Err(BackendError::Unsupported("an empty symlink target cannot be stored".into()));
        }
        let blob = fstree::encode_blob(target.as_bytes());
        let id = SymlinkId::new(blob.key.as_bytes().to_vec());
        self.put_all(vec![blob], "symlink")?;
        Ok(id)
    }

    async fn read_copy(&self, _id: &CopyId) -> BackendResult<CopyHistory> {
        Err(BackendError::Unsupported("the amber backend does not track copies".into()))
    }

    async fn write_copy(&self, _copy: &CopyHistory) -> BackendResult<CopyId> {
        Err(BackendError::Unsupported("the amber backend does not track copies".into()))
    }

    async fn get_related_copies(&self, _copy_id: &CopyId) -> BackendResult<Vec<RelatedCopy>> {
        Err(BackendError::Unsupported("the amber backend does not track copies".into()))
    }

    async fn read_tree(&self, _path: &RepoPath, id: &TreeId) -> BackendResult<Tree> {
        let k = typed_key(id.as_bytes(), &[Type::DirLeaf, Type::DirNode], "tree")?;
        let entries = fstree::collect_entries(k, |kk| self.store.get(kk)).map_err(|e| {
            if e.missing_object().is_some() || e.is_not_found() {
                BackendError::ObjectNotFound {
                    object_type: "tree".into(),
                    hash: k.to_string(),
                    source: Box::new(e),
                }
            } else {
                BackendError::ReadObject {
                    object_type: "tree".into(),
                    hash: k.to_string(),
                    source: Box::new(e),
                }
            }
        })?;
        let mut extra = Vec::new();
        let mut out = Vec::with_capacity(entries.len());
        for e in &entries {
            let name = std::str::from_utf8(&e.name).map_err(|err| BackendError::InvalidUtf8 {
                object_type: "tree".into(),
                hash: k.to_string(),
                source: err,
            })?;
            let Some(value) = self.entry_to_tree_value(e, &mut extra)? else { continue };
            let name = RepoPathComponentBuf::new(name).map_err(to_other)?;
            out.push((name, value));
        }
        if !extra.is_empty() {
            self.put_all(extra, "symlink")?;
        }
        Ok(Tree::from_sorted_entries(out))
    }

    async fn write_tree(&self, _path: &RepoPath, contents: &Tree) -> BackendResult<TreeId> {
        let mut builder = DirBuilder::new(ItemChunker::new(ITEM_BITS));
        let mut objects = Vec::new();
        let mut emit = |o: Object| -> Result<(), Infallible> {
            objects.push(o);
            Ok(())
        };
        // jj's order (bytewise on the UTF-8 name) is amber's order (bytewise on the name).
        for entry in contents.entries() {
            let e = self.tree_value_to_entry(entry.name().as_internal_str(), entry.value())?;
            builder.add_entry(&mut emit, e).map_err(|e| BackendError::WriteObject {
                object_type: "tree",
                source: format!("{e:?}").into(),
            })?;
        }
        let root = builder.finish(&mut emit).map_err(|e| BackendError::WriteObject {
            object_type: "tree",
            source: format!("{e:?}").into(),
        })?;
        self.put_all(objects, "tree")?;
        Ok(TreeId::new(root.as_bytes().to_vec()))
    }

    async fn read_commit(&self, id: &CommitId) -> BackendResult<Commit> {
        let Some(k) = self.commit_key(id)? else {
            return Ok(make_root_commit(self.root_change_id.clone(), self.empty_tree_id.clone()));
        };
        let bytes = self.get(k, "commit")?;
        let c = AmberCommit::decode(&bytes).map_err(|e| BackendError::ReadObject {
            object_type: "commit".into(),
            hash: k.to_string(),
            source: Box::new(e),
        })?;
        Ok(convert::commit_from_amber(k, &c, &self.root_commit_id))
    }

    async fn write_commit(
        &self,
        contents: Commit,
        sign_with: Option<&mut SigningFn>,
    ) -> BackendResult<(CommitId, Commit)> {
        assert!(contents.secure_sig.is_none(), "commit.secure_sig was set");
        let mut c = convert::commit_to_amber(&contents, &self.root_commit_id)
            .map_err(|e| BackendError::WriteObject { object_type: "commit", source: e.into() })?;
        if let Some(sign) = sign_with {
            let payload = c
                .signature_payload()
                .map_err(|e| BackendError::WriteObject { object_type: "commit", source: Box::new(e) })?;
            c.signature = sign(&payload).map_err(to_other)?;
        }
        let (k, bytes) = c
            .object()
            .map_err(|e| BackendError::WriteObject { object_type: "commit", source: Box::new(e) })?;
        self.store
            .put(k, &bytes)
            .map_err(|e| BackendError::WriteObject { object_type: "commit", source: Box::new(e) })?;
        // Return what a read gives back: predecessors are not stored, and a signature comes back
        // with its payload.
        let stored = convert::commit_from_amber(k, &c, &self.root_commit_id);
        debug_assert!(c.signature.is_empty() || stored.secure_sig.is_some());
        Ok((CommitId::new(k.as_bytes().to_vec()), stored))
    }

    fn get_copy_records(
        &self,
        _paths: Option<&[RepoPathBuf]>,
        _root: &CommitId,
        _head: &CommitId,
    ) -> BackendResult<BoxStream<'_, BackendResult<CopyRecord>>> {
        Ok(futures::stream::empty().boxed())
    }

    fn gc(&self, _index: &dyn Index, _keep_newer: SystemTime) -> BackendResult<()> {
        // Objects live as long as dstore references reach them; the local packstore is a cache that
        // keeps everything jj ever wrote.
        Ok(())
    }
}

const _: () = {
    const fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<AmberBackend>();
};

src/bookmarks.rs:
//! Remote-tracking bookmarks for dstore remotes, the way `jj git fetch` and `jj git push` keep them.
//!
//! Fetch records every branch under the remote's prefix as the remote bookmark `name@remote`, merges
//! it into the local bookmark when tracked, and abandons commits that only the old remote position
//! kept visible (as `jj git fetch` does). Push compares each local bookmark with its tracked remote
//! bookmark and yields the reference updates to make.

use std::collections::{BTreeMap, BTreeSet};
use std::sync::Arc;

use futures::TryStreamExt as _;
use jj_lib::backend::{BackendError, CommitId};
use jj_lib::commit::Commit;
use jj_lib::index::IndexError;
use jj_lib::merge::Diff;
use jj_lib::op_store::{RefTarget, RemoteRef, RemoteRefState};
use jj_lib::ref_name::{RefName, RefNameBuf, RemoteName};
use jj_lib::refs::{LocalAndRemoteRef, RefPushAction, classify_ref_push_action};
use jj_lib::repo::{MutableRepo, Repo as _};
use jj_lib::revset::{RevsetEvaluationError, RevsetExpression, RevsetStreamExt as _};
use jj_lib::view::View;

#[derive(Debug, thiserror::Error)]
pub enum ImportError {
    #[error(transparent)]
    Backend(#[from] BackendError),
    #[error(transparent)]
    Index(#[from] IndexError),
    #[error(transparent)]
    Revset(#[from] RevsetEvaluationError),
}

/// What a fetch changed.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct ImportStats {
    /// Remote bookmarks whose target changed, with the new target (`None`: deleted on the remote).
    pub changed: Vec<(RefNameBuf, Option<CommitId>)>,
    /// Commits no longer visible because the remote moved away from them.
    pub abandoned: Vec<CommitId>,
}

/// Makes `name@remote` point where the remote's branches point now: `fetched` is every branch under
/// the remote's prefix. Remote bookmarks missing from `fetched` were deleted on the remote. The
/// commits of `fetched` must be in the store. New remote bookmarks are tracked when `track_new`.
pub async fn import_remote_branches(
    mut_repo: &mut MutableRepo,
    remote: &RemoteName,
    fetched: &BTreeMap<RefNameBuf, CommitId>,
    track_new: bool,
) -> Result<ImportStats, ImportError> {
    mut_repo.ensure_remote(remote);
    let existing: BTreeMap<RefNameBuf, RemoteRef> =
        mut_repo.view().remote_bookmarks(remote).map(|(name, r)| (name.to_owned(), r.clone())).collect();
    let names: BTreeSet<&RefNameBuf> = existing.keys().chain(fetched.keys()).collect();

    let mut updates = Vec::new();
    for name in names {
        let new_target = fetched.get(name).map_or_else(RefTarget::absent, |id| RefTarget::normal(id.clone()));
        let old = existing.get(name).cloned().unwrap_or_else(RemoteRef::absent);
        if old.target != new_target {
            updates.push((name.clone(), old, new_target));
        }
    }

    // Make the new commits and their ancestors visible before bookmarks point at them.
    let store = Arc::clone(mut_repo.store());
    let mut heads: Vec<Commit> = Vec::new();
    for (_, _, target) in &updates {
        for id in target.added_ids() {
            heads.push(store.get_commit_async(id).await?);
        }
    }
    mut_repo.add_heads(&heads).await?;

    let mut stats = ImportStats::default();
    let mut hidable: Vec<CommitId> = Vec::new();
    for (name, old, new_target) in updates {
        let symbol = name.to_remote_symbol(remote);
        hidable.extend(old.target.added_ids().cloned());
        let state = if old.is_present() || old.is_tracked() {
            old.state
        } else if track_new {
            RemoteRefState::Tracked
        } else {
            RemoteRefState::New
        };
        let new_ref = RemoteRef { target: new_target.clone(), state };
        if new_ref.is_tracked() {
            mut_repo.merge_local_bookmark(symbol.name, old.tracked_target(), &new_ref.target).await?;
        }
        mut_repo.set_remote_bookmark(symbol, new_ref);
        stats.changed.push((name, new_target.as_normal().cloned()));
    }
    if !hidable.is_empty() {
        stats.abandoned = abandon_unreachable(mut_repo, hidable).await?;
    }
    Ok(stats)
}

/// Abandons the commits that only the old remote positions `hidable` kept visible: what is not an
/// ancestor of a local bookmark, of an untracked remote bookmark, or of the root.
async fn abandon_unreachable(
    mut_repo: &mut MutableRepo,
    hidable: Vec<CommitId>,
) -> Result<Vec<CommitId>, ImportError> {
    let view = mut_repo.view();
    let pinned_local: Vec<CommitId> =
        view.local_bookmarks().flat_map(|(_, t)| t.added_ids()).cloned().collect();
    let pinned_remote: Vec<CommitId> = view
        .all_remote_bookmarks()
        .filter(|(_, r)| !r.is_tracked())
        .flat_map(|(_, r)| r.target.added_ids())
        .cloned()
        .collect();
    let pinned = RevsetExpression::union_all(&[
        RevsetExpression::commits(pinned_local),
        RevsetExpression::commits(pinned_remote).intersection(&RevsetExpression::visible_heads().ancestors()),
        RevsetExpression::root(),
    ]);
    let abandoned_expr = pinned
        .range(&RevsetExpression::commits(hidable))
        .intersection(&RevsetExpression::visible_heads().ancestors());
    let abandoned: Vec<Commit> =
        abandoned_expr.evaluate(mut_repo)?.stream().commits(mut_repo.store()).try_collect().await?;
    for commit in &abandoned {
        mut_repo.record_abandoned_commit(commit);
    }
    // Descendants of abandoned commits (a working-copy commit on top, say) move to their parents.
    mut_repo.rebase_descendants().await?;
    Ok(abandoned.iter().map(|c| c.id().clone()).collect())
}

/// Which bookmarks a push considers.
#[derive(Clone, Debug, Default)]
pub struct PushSelection {
    /// Named bookmarks: pushed whatever their state, new or deleted ones included.
    pub names: Vec<RefNameBuf>,
    /// Every local bookmark, new ones included.
    pub all: bool,
    /// Also push deletions of tracked bookmarks deleted locally.
    pub deleted: bool,
}

/// One reference to move: `before` is the tracked remote target, `after` the local one.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PushUpdate {
    pub name: RefNameBuf,
    pub diff: Diff<Option<CommitId>>,
}

/// A bookmark the push cannot move, and what to do about it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Rejected {
    pub name: RefNameBuf,
    pub message: String,
    pub hint: Option<String>,
}

/// The updates a push makes. Without names or `all`, it considers the tracked bookmarks: those that
/// moved locally, and with `deleted` those deleted locally.
pub fn plan_push(view: &View, remote: &RemoteName, sel: &PushSelection) -> (Vec<PushUpdate>, Vec<Rejected>) {
    let mut updates = Vec::new();
    let mut rejected = Vec::new();
    let mut unknown = Vec::new();
    let mut consider = |name: &RefName, targets: LocalAndRemoteRef, explicit: bool| {
        let symbol = name.to_remote_symbol(remote);
        let reject =
            |message: String, hint: Option<String>| Rejected { name: name.to_owned(), message, hint };
        match classify_ref_push_action(targets) {
            RefPushAction::AlreadyMatches => {}
            RefPushAction::LocalConflicted => rejected.push(reject(
                format!("Bookmark {} is conflicted", name.as_symbol()),
                Some("Run `ajj bookmark list` to inspect, and use `ajj bookmark set` to fix it up.".into()),
            )),
            RefPushAction::RemoteConflicted => rejected.push(reject(
                format!("Bookmark {symbol} is conflicted"),
                Some("Run `ajj dstore fetch` to update the conflicted remote bookmark.".into()),
            )),
            RefPushAction::RemoteUntracked => rejected.push(reject(
                format!("Non-tracking remote bookmark {symbol} exists"),
                Some(format!("Run `ajj bookmark track {symbol}` to import the remote bookmark.")),
            )),
            RefPushAction::Update(diff) => {
                if diff.after.is_none() && !(explicit || sel.deleted) {
                    return;
                }
                if !(targets.remote_ref.is_tracked() || explicit || sel.all) {
                    return;
                }
                updates.push(PushUpdate { name: name.to_owned(), diff });
            }
        }
    };
    if sel.names.is_empty() {
        for (name, targets) in view.local_remote_bookmarks(remote) {
            let tracked = targets.remote_ref.is_tracked();
            if (sel.all && targets.local_target.is_present()) || tracked {
                consider(name, targets, false);
            }
        }
    } else {
        for name in &sel.names {
            let targets = LocalAndRemoteRef {
                local_target: view.get_local_bookmark(name),
                remote_ref: view.get_remote_bookmark(name.to_remote_symbol(remote)),
            };
            if targets.local_target.is_absent() && targets.remote_ref.is_absent() {
                unknown.push(Rejected {
                    name: name.clone(),
                    message: format!("No such bookmark: {}", name.as_symbol()),
                    hint: None,
                });
                continue;
            }
            consider(name, targets, true);
        }
    }
    rejected.extend(unknown);
    (updates, rejected)
}

/// Records a pushed update: the remote bookmark now points where the local one does, tracked.
pub fn record_pushed(mut_repo: &mut MutableRepo, remote: &RemoteName, update: &PushUpdate) {
    let new_ref =
        RemoteRef { target: RefTarget::resolved(update.diff.after.clone()), state: RemoteRefState::Tracked };
    mut_repo.set_remote_bookmark(update.name.to_remote_symbol(remote), new_ref);
}

src/cli.rs:
//! The `ajj` binary: jj's CLI with the amber backend registered and the `ajj dstore` commands.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use amber_store_core::key::Key;
use dstore_client::human_bytes;
use jj_cli::cli_util::{CliRunner, CommandHelper, WorkspaceCommandHelper};
use jj_cli::command_error::{CommandError, internal_error, user_error};
use jj_cli::ui::Ui;
use jj_lib::backend::CommitId;
use jj_lib::object_id::ObjectId as _;
use jj_lib::ref_name::{RefNameBuf, RemoteName, RemoteNameBuf};
use jj_lib::repo::{Repo as _, StoreFactories};
use jj_lib::signing::Signer;
use jj_lib::workspace::{Workspace, WorkspaceInitError};

use crate::backend::{AmberBackend, BACKEND_NAME};
use crate::bookmarks::{self, PushSelection};
use crate::dstore::{self, Moved, Remote, Remotes, Session};
use crate::progress::Meter;

#[derive(clap::Parser, Clone, Debug)]
enum AjjCommand {
    #[command(subcommand)]
    Dstore(DstoreCommand),
}

/// Store commits in amber and share bookmarks through a dstore cluster
///
/// Bookmark `B` on remote `R` is the dstore reference `<prefix of R>/B`, holding the key of an amber
/// commit. `fetch` and `push` keep `B@R` in step with it, as `jj git fetch/push` do for git.
#[derive(clap::Subcommand, Clone, Debug)]
enum DstoreCommand {
    Init(InitArgs),
    Clone(CloneArgs),
    Fetch(FetchArgs),
    Push(PushArgs),
    #[command(subcommand)]
    Remote(RemoteCommand),
}

#[derive(clap::Args, Clone, Debug)]
struct NetArgs {
    /// Directory of the repository's references on the cluster: `--prefix myrepo` maps bookmark
    /// `main` to reference `myrepo/main`
    #[arg(long, default_value = "")]
    prefix: String,
    /// Custom iroh relay URL
    #[arg(long, default_value = "")]
    relay: String,
    /// Disable iroh relays (direct connections only)
    #[arg(long)]
    no_relay: bool,
    /// Disable mDNS and DNS node discovery
    #[arg(long)]
    no_discovery: bool,
}

impl NetArgs {
    fn remote(&self, ticket: &str) -> Remote {
        Remote {
            ticket: ticket.to_owned(),
            prefix: dstore::normalize_prefix(&self.prefix),
            relay: self.relay.clone(),
            no_relay: self.no_relay,
            no_discovery: self.no_discovery,
        }
    }
}

/// Create a repository whose commits are amber objects
#[derive(clap::Args, Clone, Debug)]
struct InitArgs {
    /// The destination directory
    #[arg(default_value = ".", value_hint = clap::ValueHint::DirPath)]
    destination: String,
}

/// Create a repository and fetch a dstore remote into it
#[derive(clap::Args, Clone, Debug)]
struct CloneArgs {
    /// Ticket of the dstore cluster (`dstore1…`, or node ids)
    #[arg(long, env = "DSTORE_TICKET", hide_env_values = true)]
    ticket: String,
    /// The destination directory
    #[arg(value_hint = clap::ValueHint::DirPath)]
    destination: String,
    /// Name of the remote
    #[arg(long = "remote", default_value = "origin")]
    remote_name: RemoteNameBuf,
    /// Bookmark to check out; defaults to main, master or trunk
    #[arg(long, short)]
    branch: Option<String>,
    #[command(flatten)]
    net: NetArgs,
}

/// Fetch the branches of a dstore remote
#[derive(clap::Args, Clone, Debug)]
struct FetchArgs {
    /// The remote; defaults to `origin`, or the only remote
    #[arg(long)]
    remote: Option<RemoteNameBuf>,
    /// Leave new remote bookmarks untracked
    #[arg(long)]
    no_track: bool,
    /// Ticket for this run, overriding the stored one and `$DSTORE_TICKET`
    #[arg(long)]
    ticket: Option<String>,
}

/// Push bookmarks to a dstore remote
///
/// Without `-b` or `--all`, pushes the bookmarks that track the remote and moved locally. Each
/// reference moves only if it still names the commit last fetched or pushed.
#[derive(clap::Args, Clone, Debug)]
struct PushArgs {
    /// The remote; defaults to `origin`, or the only remote
    #[arg(long)]
    remote: Option<RemoteNameBuf>,
    /// Push this bookmark (new and deleted bookmarks included); repeatable
    #[arg(long = "bookmark", short = 'b')]
    bookmarks: Vec<RefNameBuf>,
    /// Push every local bookmark
    #[arg(long, conflicts_with = "bookmarks")]
    all: bool,
    /// Also push deletions of tracked bookmarks
    #[arg(long)]
    deleted: bool,
    /// Only print what would be pushed
    #[arg(long)]
    dry_run: bool,
    /// Ticket for this run, overriding the stored one and `$DSTORE_TICKET`
    #[arg(long)]
    ticket: Option<String>,
}

/// Manage dstore remotes
#[derive(clap::Subcommand, Clone, Debug)]
enum RemoteCommand {
    /// Add a remote
    ///
    /// Without a ticket (neither `--ticket` nor `$DSTORE_TICKET`), none is stored, and fetch and push
    /// take `$DSTORE_TICKET` when they run.
    Add {
        name: RemoteNameBuf,
        /// Ticket of the dstore cluster (`dstore1…`, or node ids)
        #[arg(long, env = "DSTORE_TICKET", hide_env_values = true, default_value = "")]
        ticket: String,
        #[command(flatten)]
        net: NetArgs,
    },
    /// Remove a remote and its remote bookmarks
    Remove { name: RemoteNameBuf },
    /// List remotes
    List,
}

fn create_store_factories() -> StoreFactories {
    let mut factories = StoreFactories::empty();
    factories.add_backend(
        BACKEND_NAME,
        Box::new(|settings, store_path| Ok(Box::new(AmberBackend::load(settings, store_path)?))),
    );
    factories
}

pub fn run() -> std::process::ExitCode {
    CliRunner::init()
        .name("ajj")
        .about("Jujutsu (jj) with commits stored in amber-store and bookmarks shared through dstore")
        .version(env!("CARGO_PKG_VERSION"))
        .add_store_factories(create_store_factories())
        .add_subcommand(run_command)
        .run()
        .into()
}

async fn run_command(ui: &mut Ui, command: &CommandHelper, cmd: AjjCommand) -> Result<(), CommandError> {
    let AjjCommand::Dstore(cmd) = cmd;
    match cmd {
        DstoreCommand::Init(args) => cmd_init(ui, command, &args).await,
        DstoreCommand::Clone(args) => cmd_clone(ui, command, &args).await,
        DstoreCommand::Fetch(args) => cmd_fetch(ui, command, &args).await,
        DstoreCommand::Push(args) => cmd_push(ui, command, &args).await,
        DstoreCommand::Remote(args) => cmd_remote(ui, command, args).await,
    }
}

fn runtime() -> Result<tokio::runtime::Runtime, CommandError> {
    tokio::runtime::Builder::new_multi_thread().enable_all().build().map_err(internal_error)
}

fn backend(ws: &WorkspaceCommandHelper) -> Result<&AmberBackend, CommandError> {
    ws.repo().store().backend_impl::<AmberBackend>().ok_or_else(|| {
        user_error(format!(
            "This repository does not use the {BACKEND_NAME} backend; create one with `ajj dstore init`"
        ))
    })
}

fn map_dstore(e: dstore::Error) -> CommandError {
    match e {
        dstore::Error::Changed { .. } => user_error(e).hinted("Run `ajj dstore fetch`, then push again."),
        e => user_error(e),
    }
}

fn pick_remote(
    remotes: &Remotes,
    name: Option<&RemoteName>,
) -> Result<(RemoteNameBuf, Remote), CommandError> {
    let name: RemoteNameBuf = match name {
        Some(n) => n.to_owned(),
        None if remotes.remotes.contains_key("origin") => "origin".into(),
        None if remotes.remotes.len() == 1 => remotes.remotes.keys().next().unwrap().as_str().into(),
        None if remotes.remotes.is_empty() => {
            return Err(user_error("No dstore remote is configured")
                .hinted("Add one with `ajj dstore remote add origin --ticket <ticket> --prefix <repo>`."));
        }
        None => return Err(user_error("Several dstore remotes are configured; pick one with --remote")),
    };
    let remote = remotes
        .remotes
        .get(name.as_str())
        .cloned()
        .ok_or_else(|| user_error(format!("No such dstore remote: {}", name.as_symbol())))?;
    Ok((name, remote))
}

async fn init_workspace(
    ui: &Ui,
    command: &CommandHelper,
    wc_path: &Path,
) -> Result<WorkspaceCommandHelper, CommandError> {
    let settings = command.settings_for_new_workspace(ui, wc_path)?.0;
    let (workspace, repo) = Workspace::init_with_backend(
        &settings,
        wc_path,
        &|settings, store_path| Ok(Box::new(AmberBackend::init(settings, store_path)?)),
        Signer::from_settings(&settings).map_err(WorkspaceInitError::SignInit)?,
    )
    .await?;
    command.for_workable_repo(ui, workspace, repo)
}

fn prepare_destination(command: &CommandHelper, destination: &str) -> Result<(PathBuf, bool), CommandError> {
    let wc_path = command.cwd().join(destination);
    let existed = wc_path.exists();
    if existed && wc_path.join(".jj").exists() {
        return Err(user_error(format!("{} is already a jj repository", wc_path.display())));
    }
    if existed && destination != "." && std::fs::read_dir(&wc_path)?.next().is_some() {
        return Err(user_error("Destination path exists and is not an empty directory"));
    }
    std::fs::create_dir_all(&wc_path)?;
    let wc_path = wc_path.canonicalize()?;
    Ok((wc_path, existed))
}

async fn cmd_init(ui: &mut Ui, command: &CommandHelper, args: &InitArgs) -> Result<(), CommandError> {
    let (wc_path, _) = prepare_destination(command, &args.destination)?;
    init_workspace(ui, command, &wc_path).await?;
    writeln!(ui.status(), "Initialized repo in \"{}\"", wc_path.display())?;
    Ok(())
}

async fn cmd_clone(ui: &mut Ui, command: &CommandHelper, args: &CloneArgs) -> Result<(), CommandError> {
    let remote = args.net.remote(&args.ticket);
    remote.validate().map_err(user_error)?;
    let (wc_path, existed) = prepare_destination(command, &args.destination)?;
    let result = async {
        let mut ws = init_workspace(ui, command, &wc_path).await?;
        let amber_dir = backend(&ws)?.path().to_owned();
        let mut remotes = Remotes::default();
        remotes.remotes.insert(args.remote_name.as_str().to_owned(), remote.clone());
        remotes.save(&amber_dir).map_err(user_error)?;
        writeln!(ui.status(), "Fetching into new repo in \"{}\"", wc_path.display())?;
        fetch_remote(ui, &mut ws, &args.remote_name, &remote, true).await?;
        Ok::<_, CommandError>(ws)
    }
    .await;
    let mut ws = match result {
        Ok(ws) => ws,
        Err(e) => {
            let _ = std::fs::remove_dir_all(wc_path.join(".jj"));
            if !existed {
                let _ = std::fs::remove_dir(&wc_path);
            }
            return Err(e);
        }
    };

    let view = ws.repo().view();
    let candidates: Vec<String> = match &args.branch {
        Some(b) => vec![b.clone()],
        None => ["main", "master", "trunk"].iter().map(|s| s.to_string()).collect(),
    };
    let working = candidates.into_iter().find_map(|b| {
        let name = RefNameBuf::from(b.as_str());
        let target =
            view.get_remote_bookmark(name.to_remote_symbol(&args.remote_name)).target.as_normal().cloned();
        target.map(|id| (name, id))
    });
    match working {
        Some((name, id)) => {
            let mut tx = ws.start_transaction();
            let commit = tx.repo().store().get_commit_async(&id).await?;
            tx.check_out(&commit)?;
            tx.finish(ui, format!("check out dstore remote's branch: {}", name.as_symbol())).await?;
        }
        None if args.branch.is_some() => {
            return Err(user_error(format!(
                "No branch {} on remote {}",
                args.branch.as_deref().unwrap_or_default(),
                args.remote_name.as_symbol()
            )));
        }
        None => {}
    }
    Ok(())
}

async fn cmd_fetch(ui: &mut Ui, command: &CommandHelper, args: &FetchArgs) -> Result<(), CommandError> {
    let mut ws = command.workspace_helper(ui).await?;
    let remotes = Remotes::load(backend(&ws)?.path()).map_err(user_error)?;
    let (name, remote) = pick_remote(&remotes, args.remote.as_deref())?;
    let remote = remote.for_run(args.ticket.as_deref()).map_err(user_error)?;
    fetch_remote(ui, &mut ws, &name, &remote, !args.no_track).await
}

/// Lists the remote's branches, copies their commits into the local store, and updates the remote
/// bookmarks in one transaction.
async fn fetch_remote(
    ui: &Ui,
    ws: &mut WorkspaceCommandHelper,
    remote_name: &RemoteName,
    remote: &Remote,
    track_new: bool,
) -> Result<(), CommandError> {
    let store = Arc::clone(backend(ws)?.store());
    let meter = Meter::new(ui);
    let rt = runtime()?;
    let result = rt.block_on(async {
        meter.phase("Connecting to dstore");
        let session = Session::dial(remote).await?;
        let result = async {
            meter.phase(format!("Listing {}", remote.ref_prefix()));
            let (branches, other) = dstore::list_branches(&session.cluster, &remote.ref_prefix()).await?;
            let mut moved = Moved::default();
            for b in &branches {
                meter.phase(format!("Fetching {}", remote.ref_name(&b.bookmark)));
                moved += dstore::fetch(&session.cluster, &store, b.key, meter.callback()).await?;
            }
            Ok::<_, dstore::Error>((branches, other, moved))
        }
        .await;
        meter.phase("Disconnecting");
        session.close().await;
        result
    });
    meter.clear();
    drop(rt);
    let (branches, other, moved) = result.map_err(map_dstore)?;
    if moved.objects > 0 {
        writeln!(ui.status(), "Fetched {} objects ({}).", moved.objects, human_bytes(moved.bytes))?;
    }

    for name in &other {
        writeln!(ui.warning_default(), "Skipping dstore reference {name}: it does not name a commit")?;
    }
    let fetched: BTreeMap<RefNameBuf, CommitId> = branches
        .iter()
        .map(|b| (RefNameBuf::from(b.bookmark.as_str()), CommitId::new(b.key.as_bytes().to_vec())))
        .collect();

    let mut tx = ws.start_transaction();
    let stats = bookmarks::import_remote_branches(tx.repo_mut(), remote_name, &fetched, track_new)
        .await
        .map_err(internal_error)?;
    if stats.changed.is_empty() {
        writeln!(ui.status(), "Nothing changed.")?;
        return Ok(());
    }
    let mut summary = String::new();
    for (name, target) in &stats.changed {
        let symbol = name.to_remote_symbol(remote_name);
        match target {
            Some(id) => writeln!(summary, "  {symbol} -> {}", short(id)).unwrap(),
            None => writeln!(summary, "  {symbol} deleted").unwrap(),
        }
    }
    if !stats.abandoned.is_empty() {
        writeln!(summary, "Abandoned {} commits that are no longer reachable.", stats.abandoned.len())
            .unwrap();
    }
    tx.finish(ui, format!("fetch from dstore remote {}", remote_name.as_symbol())).await?;
    write!(ui.status(), "Fetched from {}:\n{summary}", remote_name.as_symbol())?;
    Ok(())
}

async fn cmd_push(ui: &mut Ui, command: &CommandHelper, args: &PushArgs) -> Result<(), CommandError> {
    let mut ws = command.workspace_helper(ui).await?;
    let remotes = Remotes::load(backend(&ws)?.path()).map_err(user_error)?;
    let (remote_name, remote) = pick_remote(&remotes, args.remote.as_deref())?;
    let remote = remote.for_run(args.ticket.as_deref()).map_err(user_error)?;
    let store = Arc::clone(backend(&ws)?.store());

    let sel = PushSelection { names: args.bookmarks.clone(), all: args.all, deleted: args.deleted };
    let (updates, rejected) = bookmarks::plan_push(ws.repo().view(), &remote_name, &sel);
    for r in &rejected {
        writeln!(ui.warning_default(), "{}", r.message)?;
        if let Some(hint) = &r.hint {
            writeln!(ui.hint_default(), "{hint}")?;
        }
    }
    if !rejected.is_empty() {
        return Err(user_error("Refusing to push: some bookmarks cannot be pushed"));
    }
    if updates.is_empty() {
        writeln!(ui.status(), "Nothing changed.")?;
        return Ok(());
    }
    let root = ws.repo().store().root_commit_id().clone();
    let mut plan = Vec::new();
    for u in &updates {
        if u.diff.after.as_ref() == Some(&root) {
            return Err(user_error(format!("Bookmark {} points at the root commit", u.name.as_symbol())));
        }
        let key_of = |id: &Option<CommitId>| -> Result<Option<Key>, CommandError> {
            match id {
                None => Ok(None),
                Some(id) => backend(&ws)?.commit_key(id).map_err(internal_error),
            }
        };
        plan.push((
            u.clone(),
            remote.ref_name(u.name.as_str()),
            key_of(&u.diff.before)?,
            key_of(&u.diff.after)?,
        ));
    }

    writeln!(ui.status(), "Changes to push to {}:", remote_name.as_symbol())?;
    for (u, ref_name, _, _) in &plan {
        let line = match (&u.diff.before, &u.diff.after) {
            (None, Some(a)) => format!("Add bookmark {} to {}", u.name.as_symbol(), short(a)),
            (Some(b), Some(a)) => {
                format!("Move bookmark {} from {} to {}", u.name.as_symbol(), short(b), short(a))
            }
            (Some(b), None) => format!("Delete bookmark {} from {}", u.name.as_symbol(), short(b)),
            (None, None) => continue,
        };
        writeln!(ui.status(), "  {line} (reference {ref_name})")?;
    }
    if args.dry_run {
        writeln!(ui.status(), "Dry-run requested, not pushing.")?;
        return Ok(());
    }

    let settings = ws.settings();
    let user = dstore::ref_user(settings.user_name(), settings.user_email());
    let meter = Meter::new(ui);
    let rt = runtime()?;
    let results = rt.block_on(async {
        meter.phase("Connecting to dstore");
        let session = Session::dial(&remote).await?;
        let mut results = Vec::new();
        for (_, ref_name, before, after) in &plan {
            let r = match (before, after) {
                (_, Some(a)) => {
                    meter.phase(format!("Pushing {ref_name}"));
                    dstore::put_branch(
                        &session.cluster,
                        &store,
                        ref_name,
                        *a,
                        *before,
                        &user,
                        meter.callback(),
                    )
                    .await
                }
                (Some(b), None) => {
                    meter.phase(format!("Deleting {ref_name}"));
                    dstore::delete_branch(&session.cluster, ref_name, *b).await.map(|()| Moved::default())
                }
                (None, None) => Ok(Moved::default()),
            };
            results.push(r);
        }
        meter.phase("Disconnecting");
        session.close().await;
        Ok::<_, dstore::Error>(results)
    });
    meter.clear();
    drop(rt);
    let results = results.map_err(map_dstore)?;
    let mut moved = Moved::default();
    for m in results.iter().flatten() {
        moved += *m;
    }
    writeln!(ui.status(), "Uploaded {} objects ({}).", moved.objects, human_bytes(moved.bytes))?;

    let mut tx = ws.start_transaction();
    let mut first_err = None;
    for ((u, _, _, _), r) in plan.iter().zip(results) {
        match r {
            Ok(_) => bookmarks::record_pushed(tx.repo_mut(), &remote_name, u),
            Err(e) => {
                writeln!(ui.warning_default(), "Failed to push {}: {e}", u.name.as_symbol())?;
                first_err.get_or_insert(e);
            }
        }
    }
    if tx.repo().has_changes() {
        tx.finish(ui, format!("push to dstore remote {}", remote_name.as_symbol())).await?;
    }
    match first_err {
        Some(e) => Err(map_dstore(e)),
        None => Ok(()),
    }
}

async fn cmd_remote(ui: &mut Ui, command: &CommandHelper, cmd: RemoteCommand) -> Result<(), CommandError> {
    let mut ws = command.workspace_helper_no_snapshot(ui).await?;
    let amber_dir = backend(&ws)?.path().to_owned();
    let mut remotes = Remotes::load(&amber_dir).map_err(user_error)?;
    match cmd {
        RemoteCommand::Add { name, ticket, net } => {
            if name.as_str() == "git" {
                return Err(user_error("The remote name `git` is reserved by jj"));
            }
            if remotes.remotes.contains_key(name.as_str()) {
                return Err(user_error(format!("Remote {} already exists", name.as_symbol())));
            }
            let remote = net.remote(&ticket);
            remote.validate().map_err(user_error)?;
            remotes.remotes.insert(name.as_str().to_owned(), remote);
            remotes.save(&amber_dir).map_err(user_error)?;
        }
        RemoteCommand::Remove { name } => {
            if remotes.remotes.remove(name.as_str()).is_none() {
                return Err(user_error(format!("No such dstore remote: {}", name.as_symbol())));
            }
            remotes.save(&amber_dir).map_err(user_error)?;
            let mut tx = ws.start_transaction();
            tx.repo_mut().remove_remote(&name);
            if tx.repo().has_changes() {
                tx.finish(ui, format!("remove dstore remote {}", name.as_symbol())).await?;
            }
        }
        RemoteCommand::List => {
            let mut out = ui.stdout();
            for (name, r) in &remotes.remotes {
                let prefix = if r.prefix.is_empty() {
                    String::new()
                } else {
                    format!(" prefix={}", dstore::normalize_prefix(&r.prefix))
                };
                let ticket = if r.ticket.is_empty() { "$DSTORE_TICKET" } else { &r.ticket };
                writeln!(out, "{name} {ticket}{prefix}")?;
            }
        }
    }
    Ok(())
}

fn short(id: &CommitId) -> String {
    id.hex()[..16].to_owned()
}

