//! jj `backend::Commit` ⇄ amber `commit::Commit` (core `architecture/commits.md`, "Conflicts").
//!
//! | jj | amber |
//! | --- | --- |
//! | `parents` | key 1; a commit whose only parent is the virtual root commit has no parents |
//! | `root_tree: Merge<TreeId>` `[A0, R0, A1, …]` | key 0 is `A0`, key 8 the rest |
//! | `conflict_labels: Merge<String>` | key 9, absent when the tree is resolved or no term is labelled |
//! | `change_id` | key 7 |
//! | `description`, `author`, `committer` | keys 4, 2, 3; milliseconds ⇄ nanoseconds |
//! | `secure_sig` | key 5, over [`AmberCommit::signature_payload`] |
//! | `predecessors` | not stored (deprecated in jj, which keeps them in its operation log) |
//!
//! A commit not written by jj (dstore's working copies write them) may lack a change id or carry one
//! of another length; jj needs [`CHANGE_ID_LENGTH`] bytes, so one is derived ([`change_id_of`]).

use amber_store_core::commit::{Commit as AmberCommit, Identity};
use amber_store_core::key::{Key, Type};
use jj_lib::backend::{
    ChangeId, Commit, CommitId, MillisSinceEpoch, SecureSig, Signature, Timestamp, TreeId,
};
use jj_lib::merge::{Merge, MergeBuilder};
use jj_lib::object_id::ObjectId as _;

use crate::backend::CHANGE_ID_LENGTH;

const NANOS_PER_MILLI: i64 = 1_000_000;

#[derive(Debug, thiserror::Error)]
pub enum ConvertError {
    #[error("{what} {hex} is not a canonical {expected} key")]
    BadKey { what: &'static str, hex: String, expected: &'static str },
    #[error("the root commit can only be a commit's sole parent")]
    RootInMerge,
    #[error("{0}: time out of range (amber keeps nanoseconds in 64 bits, about 292 years around 1970)")]
    TimeRange(&'static str),
}

pub fn commit_to_amber(c: &Commit, root: &CommitId) -> Result<AmberCommit, ConvertError> {
    let parents = if c.parents.len() == 1 && c.parents[0] == *root {
        Vec::new()
    } else {
        let mut parents = Vec::with_capacity(c.parents.len());
        for p in &c.parents {
            if p == root {
                return Err(ConvertError::RootInMerge);
            }
            parents.push(key_of(p.as_bytes(), "parent", &[Type::Commit], "Commit")?);
        }
        parents
    };
    let mut trees = Vec::with_capacity(c.root_tree.as_slice().len());
    for t in c.root_tree.iter() {
        trees.push(key_of(t.as_bytes(), "tree", &[Type::DirLeaf, Type::DirNode], "DirLeaf or DirNode")?);
    }
    let tree = trees.remove(0);
    let conflict_labels = if c.root_tree.is_resolved()
        || c.conflict_labels.is_resolved()
        || c.conflict_labels.iter().all(String::is_empty)
    {
        Vec::new()
    } else {
        c.conflict_labels.iter().cloned().collect()
    };
    Ok(AmberCommit {
        tree,
        parents,
        author: identity_of(&c.author, "author")?,
        committer: identity_of(&c.committer, "committer")?,
        message: c.description.clone(),
        signature: Vec::new(),
        public_key: Vec::new(),
        change_id: c.change_id.to_bytes(),
        conflict_terms: trees,
        conflict_labels,
    })
}

pub fn commit_from_amber(k: Key, c: &AmberCommit, root: &CommitId) -> Commit {
    let parents = if c.parents.is_empty() {
        vec![root.clone()]
    } else {
        c.parents.iter().map(|p| CommitId::new(p.as_bytes().to_vec())).collect()
    };
    let root_tree: MergeBuilder<TreeId> =
        c.trees().iter().map(|t| TreeId::new(t.as_bytes().to_vec())).collect();
    let conflict_labels = if c.conflict_labels.is_empty() {
        Merge::resolved(String::new())
    } else {
        Merge::from_vec(c.conflict_labels.clone())
    };
    let secure_sig = if c.signature.is_empty() {
        None
    } else {
        // The payload is the record without key 5; a stored commit re-encodes, so this holds.
        c.signature_payload().ok().map(|data| SecureSig { data, sig: c.signature.clone() })
    };
    Commit {
        parents,
        predecessors: Vec::new(),
        root_tree: root_tree.build(),
        conflict_labels,
        change_id: change_id_of(k, c),
        description: c.message.clone(),
        author: signature_of(&c.author),
        committer: signature_of(&c.committer),
        secure_sig,
    }
}

/// The change id jj sees: the stored one when it has jj's length, otherwise 16 bytes derived from it,
/// or from the commit key when there is none. Derived ids are stable, so every reader agrees.
pub fn change_id_of(k: Key, c: &AmberCommit) -> ChangeId {
    if c.change_id.len() == CHANGE_ID_LENGTH {
        return ChangeId::new(c.change_id.clone());
    }
    let mut h = blake3::Hasher::new();
    h.update(b"ajj change id\0");
    if c.change_id.is_empty() {
        h.update(b"key\0");
        h.update(k.as_bytes());
    } else {
        h.update(b"id\0");
        h.update(&c.change_id);
    }
    ChangeId::new(h.finalize().as_bytes()[..CHANGE_ID_LENGTH].to_vec())
}

fn key_of(
    bytes: &[u8],
    what: &'static str,
    types: &[Type],
    expected: &'static str,
) -> Result<Key, ConvertError> {
    let bad = || ConvertError::BadKey { what, hex: hex::encode(bytes), expected };
    let k = Key::parse(bytes).map_err(|_| bad())?;
    if !types.contains(&k.type_()) {
        return Err(bad());
    }
    Ok(k)
}

fn identity_of(s: &Signature, what: &'static str) -> Result<Identity, ConvertError> {
    let when = s.timestamp.timestamp.0.checked_mul(NANOS_PER_MILLI).ok_or(ConvertError::TimeRange(what))?;
    Ok(Identity { name: s.name.clone(), email: s.email.clone(), when, tz_offset: s.timestamp.tz_offset })
}

fn signature_of(id: &Identity) -> Signature {
    Signature {
        name: id.name.clone(),
        email: id.email.clone(),
        timestamp: Timestamp {
            timestamp: MillisSinceEpoch(id.when.div_euclid(NANOS_PER_MILLI)),
            tz_offset: id.tz_offset,
        },
    }
}

src/dstore.rs:
//! Talking to a dstore cluster: remotes, dialing, listing branches, moving commits and references.
//!
//! A **remote** is a dstore cluster (its ticket) plus a reference-name prefix. The jj bookmark `B`
//! on remote `R` is the dstore reference `<prefix of R>/B` (just `B` without a prefix), and a
//! reference is a branch when its key is
//! a commit key. This module knows nothing about jj's view; [`crate::cli`] maps these operations onto
//! remote-tracking bookmarks.

use std::collections::BTreeMap;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use amber_store_core::key::{Key, Type};
use amber_store_core::packstore;
use dstore_client::{Cluster, Cond, Config as ClientConfig, Ctx, Logger, Progress, PullStats};
use dstore_gocompat::slog::{Attr, Handler, Level, Record};
use dstore_transport::Endpoint;
use dstore_transport_iroh::{IrohConfig, IrohEndpoint, bind_iroh, generate_secret_key, relay_mode_of};
use serde::{Deserialize, Serialize};

/// How long closing the endpoint may take (dstore's CLI uses the same bound).
const CLOSE_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(3);

#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("{0}")]
    Msg(String),
    #[error(transparent)]
    Client(#[from] dstore_client::Error),
    #[error(transparent)]
    Io(#[from] io::Error),
    #[error("dstore reference {name} changed on the remote (now {current}); fetch first")]
    Changed { name: String, current: String },
}

/// One configured dstore remote.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Remote {
    /// A `dstore1…` ticket, or node ids; empty to take `$DSTORE_TICKET` at each use.
    pub ticket: String,
    /// The directory of the repository's references, e.g. `myrepo` for `myrepo/main`; empty for
    /// references at the top level. A trailing `/` is ignored.
    #[serde(default)]
    pub prefix: String,
    /// A custom relay URL; empty for iroh's default relays.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub relay: String,
    #[serde(default, skip_serializing_if = "is_false")]
    pub no_relay: bool,
    #[serde(default, skip_serializing_if = "is_false")]
    pub no_discovery: bool,
}

fn is_false(b: &bool) -> bool {
    !*b
}

/// A prefix as stored: without trailing separators, which [`Remote::ref_prefix`] adds.
pub fn normalize_prefix(prefix: &str) -> String {
    prefix.trim_end_matches('/').to_owned()
}

impl Remote {
    /// What precedes a bookmark name in a reference name: `<prefix>/`, or nothing.
    pub fn ref_prefix(&self) -> String {
        let p = normalize_prefix(&self.prefix);
        if p.is_empty() { p } else { p + "/" }
    }

    pub fn ref_name(&self, bookmark: &str) -> String {
        self.ref_prefix() + bookmark
    }

    /// The remote as one run uses it: `ticket` given for the run, else the stored ticket, else
    /// `$DSTORE_TICKET` (dstore's working copies resolve theirs in the same order).
    pub fn for_run(&self, ticket: Option<&str>) -> Result<Remote, Error> {
        let env = std::env::var("DSTORE_TICKET").unwrap_or_default();
        let ticket = match ticket {
            Some(t) => t.to_owned(),
            None if !self.ticket.is_empty() => self.ticket.clone(),
            None if !env.is_empty() => env,
            None => {
                return Err(Error::Msg(
                    "no ticket: the remote stores none; pass --ticket or set DSTORE_TICKET".into(),
                ));
            }
        };
        let r = Remote { ticket, ..self.clone() };
        r.validate()?;
        Ok(r)
    }

    /// Checks the ticket, when one is stored, and that the prefix makes valid reference names.
    pub fn validate(&self) -> Result<(), Error> {
        if !self.ticket.is_empty() {
            dstore_ticket::parse(self.ticket.as_bytes()).map_err(|e| Error::Msg(e.to_string()))?;
        }
        if !self.ref_prefix().is_empty() {
            dstore_client::validate_name_bytes(self.ref_name("x").as_bytes())
                .map_err(|e| Error::Msg(format!("prefix {:?}: {e}", self.prefix)))?;
        }
        relay_mode_of(&self.relay, self.no_relay).map_err(Error::Msg)?;
        Ok(())
    }
}

/// The remotes of one repo, kept in `.jj/repo/store/amber/remotes.json`.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Remotes {
    #[serde(default)]
    pub remotes: BTreeMap<String, Remote>,
}

impl Remotes {
    pub fn path(amber_dir: &Path) -> PathBuf {
        amber_dir.join("remotes.json")
    }

    pub fn load(amber_dir: &Path) -> Result<Remotes, Error> {
        match std::fs::read(Self::path(amber_dir)) {
            Ok(b) => serde_json::from_slice(&b)
                .map_err(|e| Error::Msg(format!("{}: {e}", Self::path(amber_dir).display()))),
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(Remotes::default()),
            Err(e) => Err(e.into()),
        }
    }

    pub fn save(&self, amber_dir: &Path) -> Result<(), Error> {
        let path = Self::path(amber_dir);
        let tmp = path.with_extension("json.tmp");
        let mut b = serde_json::to_vec_pretty(self).map_err(|e| Error::Msg(e.to_string()))?;
        b.push(b'\n');
        std::fs::write(&tmp, b)?;
        std::fs::rename(&tmp, &path)?;
        Ok(())
    }
}

struct Discard;

impl Handler for Discard {
    fn enabled(&self, _level: Level) -> bool {
        false
    }
    fn handle(&self, _handler_attrs: &[Attr], _r: &Record) {}
}

/// dstore's client logs every dial and push at INFO; jj's own output reports what happened.
pub fn quiet_logger() -> Logger {
    Logger::new(Arc::new(Discard))
}

/// A dialed cluster, and the iroh endpoint when this process bound one.
pub struct Session {
    pub cluster: Cluster,
    endpoint: Option<Arc<IrohEndpoint>>,
}

impl Session {
    /// Binds an iroh endpoint and dials the remote's cluster. Needs a multi-thread tokio runtime.
    pub async fn dial(remote: &Remote) -> Result<Session, Error> {
        let ctx = Ctx::background();
        let ticket = dstore_ticket::parse(remote.ticket.as_bytes()).map_err(|e| Error::Msg(e.to_string()))?;
        let relay = relay_mode_of(&remote.relay, remote.no_relay).map_err(Error::Msg)?;
        let log = quiet_logger();
        let endpoint = bind_iroh(
            &ctx,
            IrohConfig {
                secret_key: generate_secret_key(),
                alpns: Vec::new(),
                relay,
                advertise: None,
                bind_addr: None,
                loopback: false,
                direct_timeout: None,
                discover: !remote.no_discovery,
                announce: false,
                logger: Some(log.clone()),
            },
        )
        .await
        .map_err(|e| Error::Msg(format!("dstore: {e}")))?;
        let ep: Arc<dyn Endpoint> = endpoint.clone();
        let cfg = ClientConfig { endpoint: Some(ep), ticket, logger: Some(log), ..ClientConfig::default() };
        match Cluster::dial(&ctx, cfg).await {
            Ok(cluster) => Ok(Session { cluster, endpoint: Some(endpoint) }),
            Err(e) => {
                Endpoint::close(&*endpoint).await;
                Err(e.into())
            }
        }
    }

    /// A session over a cluster dialed elsewhere (tests use an in-memory transport).
    pub fn from_cluster(cluster: Cluster) -> Session {
        Session { cluster, endpoint: None }
    }

    pub async fn close(self) {
        self.cluster.close();
        if let Some(ep) = self.endpoint {
            ep.close_bounded(CLOSE_TIMEOUT).await;
        }
    }
}

/// A reference under a remote's prefix.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RemoteRef {
    /// The reference name without the prefix: the bookmark name.
    pub bookmark: String,
    pub key: Key,
}

/// Lists the references whose names start with `prefix` ([`Remote::ref_prefix`]). Those naming commits are branches; the names of the others
/// (trees pushed by `dstore push` without a branch) come back separately.
pub async fn list_branches(cl: &Cluster, prefix: &str) -> Result<(Vec<RemoteRef>, Vec<String>), Error> {
    let ctx = Ctx::background();
    let infos = cl.ref_list(&ctx, prefix.as_bytes()).await?;
    let mut branches = Vec::new();
    let mut other = Vec::new();
    for info in infos {
        let Some(bookmark) = info.name.strip_prefix(prefix) else { continue };
        let key = info.key.as_deref().and_then(|k| Key::parse(k).ok());
        match key {
            Some(key) if key.type_() == Type::Commit && !bookmark.is_empty() => {
                branches.push(RemoteRef { bookmark: bookmark.to_owned(), key })
            }
            _ => other.push(info.name),
        }
    }
    Ok((branches, other))
}

/// Objects moved by a transfer.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Moved {
    pub objects: i64,
    pub bytes: i64,
}

impl std::ops::AddAssign for Moved {
    fn add_assign(&mut self, o: Moved) {
        self.objects += o.objects;
        self.bytes += o.bytes;
    }
}

/// Copies the closure of `key` (for a commit: its trees and its whole history) into `local`.
/// Subtrees already complete locally are not fetched again. Returns what was fetched.
pub async fn fetch(
    cl: &Cluster,
    local: &Arc<packstore::Store>,
    key: Key,
    prog: Option<Progress>,
) -> Result<Moved, Error> {
    let ctx = Ctx::background();
    let mut st = PullStats::default();
    cl.pull_tree(&ctx, Arc::clone(local), key, &mut st, prog).await?;
    Ok(Moved { objects: st.fetched, bytes: st.bytes })
}

/// Uploads the closure of `key` and points the reference `name` at it, provided the reference still
/// names `expected_old` (`None`: the reference must not exist). Returns what was uploaded.
pub async fn put_branch(
    cl: &Cluster,
    local: &Arc<packstore::Store>,
    name: &str,
    key: Key,
    expected_old: Option<Key>,
    user: &str,
    prog: Option<Progress>,
) -> Result<Moved, Error> {
    let ctx = Ctx::background();
    let cond = keyed(expected_old);
    match cl.push(&ctx, Arc::clone(local), key, name, user, cond, prog).await {
        Ok(ps) => Ok(Moved { objects: ps.uploaded, bytes: ps.bytes }),
        Err(e) => match e.cas_mismatch() {
            // The reference already names our commit: an earlier push got this far.
            Some(cm) if cm.has_current && cm.current == key.as_bytes() => Ok(Moved::default()),
            Some(cm) => Err(Error::Changed { name: name.to_owned(), current: describe_current(cm) }),
            None => Err(e.into()),
        },
    }
}

/// Deletes the reference `name`, provided it still names `expected_old`.
pub async fn delete_branch(cl: &Cluster, name: &str, expected_old: Key) -> Result<(), Error> {
    let ctx = Ctx::background();
    match cl.ref_delete(&ctx, name, &keyed(Some(expected_old))).await {
        Ok(()) => Ok(()),
        Err(e) if e.is_unknown_ref() => Ok(()),
        Err(e) => match e.cas_mismatch() {
            Some(cm) if !cm.has_current => Ok(()),
            Some(cm) => Err(Error::Changed { name: name.to_owned(), current: describe_current(cm) }),
            None => Err(e.into()),
        },
    }
}

fn keyed(expected_old: Option<Key>) -> Cond {
    Cond {
        keyed: true,
        expected_old: expected_old.map(|k| k.as_bytes().to_vec()).unwrap_or_default(),
        ..Cond::default()
    }
}

fn describe_current(cm: &dstore_client::CasMismatch) -> String {
    if cm.has_current { hex::encode(&cm.current) } else { "absent".to_owned() }
}

/// The user recorded on references: dstore's user-name rules are stricter than jj's.
pub fn ref_user(name: &str, email: &str) -> String {
    for candidate in [email, name] {
        if !candidate.is_empty() && dstore_client::validate_user_bytes(candidate.as_bytes()).is_ok() {
            return candidate.to_owned();
        }
    }
    String::new()
}

#[cfg(test)]
mod tests {
    use super::*;

    const T1: &str = "5b7f9fd5b7d899a67bdf2acb82a52d164593cb836f5a3b7546899bf5f3334c27";
    const T2: &str = "6c8fa0e6c8e9aab78ce03bdc93b63e275604dc947c4b86578a9aac06a4445d38";

    #[test]
    fn a_run_ticket_overrides_the_stored_one() {
        let stored = Remote { ticket: T1.into(), prefix: "p".into(), ..Remote::default() };
        assert_eq!(stored.for_run(None).unwrap().ticket, T1);
        let run = stored.for_run(Some(T2)).unwrap();
        assert_eq!(run.ticket, T2);
        assert_eq!(run.prefix, "p");
        assert!(stored.for_run(Some("not a ticket")).is_err());
    }

    #[test]
    fn a_remote_may_store_no_ticket() {
        let r = Remote { prefix: "p".into(), ..Remote::default() };
        r.validate().unwrap();
        assert_eq!(r.for_run(Some(T1)).unwrap().ticket, T1);
        let json =
            serde_json::to_string(&Remotes { remotes: [("origin".into(), r.clone())].into() }).unwrap();
        let back: Remotes = serde_json::from_str(&json).unwrap();
        assert_eq!(back.remotes["origin"], r);
    }

    #[test]
    fn the_prefix_is_a_directory() {
        let at = |prefix: &str| Remote { prefix: prefix.into(), ..Remote::default() };
        assert_eq!(at("myrepo").ref_name("main"), "myrepo/main");
        assert_eq!(at("myrepo/").ref_name("main"), "myrepo/main");
        assert_eq!(at("myrepo//").ref_name("main"), "myrepo/main");
        assert_eq!(at("team/myrepo").ref_name("main"), "team/myrepo/main");
        assert_eq!(at("").ref_name("main"), "main");
        assert_eq!(at("myrepo").ref_prefix(), "myrepo/");
        assert_eq!(at("").ref_prefix(), "");
        assert_eq!(normalize_prefix("myrepo/"), "myrepo");
    }
}

src/lib.rs:
//! ajj: jj (Jujutsu) whose commits are amber-store objects, with bookmarks shared through dstore.
//!
//! - [`backend`]: the jj `Backend` over a local core-rs packstore; every jj id is an amber key.
//! - [`convert`]: jj's commit record to amber's Commit object and back.
//! - [`dstore`]: remotes, dialing a cluster, listing branches, moving closures and references.
//! - [`bookmarks`]: remote-tracking bookmarks updated by fetch and push, as `jj git` keeps them.
//! - [`progress`]: the one-line transfer display.
//! - [`cli`]: the `ajj` binary.

pub mod backend;
pub mod bookmarks;
pub mod cli;
pub mod convert;
pub mod dstore;
pub mod progress;

src/progress.rs:
//! A one-line progress display for dstore transfers.
//!
//! It is drawn only where jj draws its own progress (`Ui::progress_output`: stderr is a terminal,
//! progress is enabled, and `--quiet` is off), overwritten in place and erased when the transfer
//! ends; the commands print their summaries through `ui.status()` either way.

use std::io::{self, Stderr};
use std::sync::{Arc, Mutex, PoisonError};
use std::time::{Duration, Instant};

use dstore_client::{Progress, ProgressReport, human_bytes, rate};
use jj_cli::ui::{ProgressOutput, Ui};

/// Redraws at most this often; the last report of a phase is always drawn.
const INTERVAL: Duration = Duration::from_millis(100);

pub struct Meter {
    state: Mutex<State>,
}

struct State {
    out: Option<ProgressOutput<Stderr>>,
    label: String,
    phase_start: Instant,
    last_draw: Option<Instant>,
    drawn: bool,
}

impl Meter {
    pub fn new(ui: &Ui) -> Arc<Meter> {
        Arc::new(Meter {
            state: Mutex::new(State {
                out: ui.progress_output(),
                label: String::new(),
                phase_start: Instant::now(),
                last_draw: None,
                drawn: false,
            }),
        })
    }

    /// Starts a phase: `label` alone until the first report, e.g. "Connecting to dstore".
    pub fn phase(&self, label: impl Into<String>) {
        let mut st = self.state.lock().unwrap_or_else(PoisonError::into_inner);
        st.label = label.into();
        st.phase_start = Instant::now();
        st.last_draw = None;
        let text = format!("{}…", st.label);
        st.draw(&text);
    }

    /// The callback dstore's transfers report to, drawing `label: counts`; `None` without a display.
    pub fn callback(self: &Arc<Self>) -> Option<Progress> {
        let has_output = self.state.lock().unwrap_or_else(PoisonError::into_inner).out.is_some();
        has_output.then(|| {
            let me = Arc::clone(self);
            Arc::new(move |r: &ProgressReport| me.report(r)) as Progress
        })
    }

    fn report(&self, r: &ProgressReport) {
        let mut st = self.state.lock().unwrap_or_else(PoisonError::into_inner);
        let now = Instant::now();
        let finished = r.total_objects > 0 && r.objects >= r.total_objects;
        if !finished && st.last_draw.is_some_and(|t| now - t < INTERVAL) {
            return;
        }
        st.last_draw = Some(now);
        let text = format!("{}: {}", st.label, describe(r, now - st.phase_start));
        st.draw(&text);
    }

    /// Erases the line.
    pub fn clear(&self) {
        let mut st = self.state.lock().unwrap_or_else(PoisonError::into_inner);
        if st.drawn
            && let Some(out) = &mut st.out
        {
            let _ = write!(out, "\r\x1b[K");
            let _ = out.flush();
        }
        st.drawn = false;
    }
}

impl Drop for Meter {
    fn drop(&mut self) {
        self.clear();
    }
}

impl State {
    fn draw(&mut self, text: &str) {
        let Some(out) = &mut self.out else { return };
        // A pty without a size (script, some CI runners) reports 0 columns.
        let width = out.term_width().map(usize::from).filter(|w| *w >= 20).unwrap_or(80) - 1;
        let text: String = text.chars().take(width).collect();
        let r: io::Result<()> = (|| {
            write!(out, "\r{text}\x1b[K")?;
            out.flush()
        })();
        self.drawn = r.is_ok();
    }
}

/// `12/40 objects, 1.2 MiB/3.4 MiB (35%), 2.1 MiB/s`; totals appear once the transfer knows them.
pub fn describe(r: &ProgressReport, took: Duration) -> String {
    let mut s = if r.total_objects > 0 {
        format!("{}/{} objects", r.objects, r.total_objects)
    } else {
        format!("{} objects", r.objects)
    };
    if r.total_bytes > 0 {
        let pct = (r.bytes as f64 / r.total_bytes as f64 * 100.0).clamp(0.0, 100.0);
        s += &format!(", {}/{} ({pct:.0}%)", human_bytes(r.bytes), human_bytes(r.total_bytes));
    } else {
        s += &format!(", {}", human_bytes(r.bytes));
    }
    if r.bytes > 0 && took >= Duration::from_millis(500) {
        s += &format!(", {}", rate(r.bytes, took));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn report(objects: i64, total_objects: i64, bytes: i64, total_bytes: i64) -> ProgressReport {
        ProgressReport { objects, total_objects, bytes, total_bytes, nodes: Vec::new() }
    }

    #[test]
    fn describes_what_is_known() {
        let fast = Duration::from_millis(10);
        assert_eq!(describe(&report(3, 0, 2048, 0), fast), "3 objects, 2.0 KiB");
        assert_eq!(describe(&report(12, 40, 1 << 20, 4 << 20), fast), "12/40 objects, 1.0 MiB/4.0 MiB (25%)");
        assert_eq!(
            describe(&report(40, 40, 4 << 20, 4 << 20), Duration::from_secs(2)),
            "40/40 objects, 4.0 MiB/4.0 MiB (100%), 2.0 MiB/s"
        );
    }
}

tests/backend.rs:
//! The amber backend on its own: every jj object round-trips, and the stored objects are the amber
//! objects core would build (file keys match `ingest`, commits decode with core's strict decoder).

use std::sync::Arc;

use ajj::backend::{AmberBackend, CHANGE_ID_LENGTH, empty_dir_key};
use amber_store_core::commit::{Commit as AmberCommit, Identity};
use amber_store_core::fstree;
use amber_store_core::ingest;
use amber_store_core::key::{Key, Type};
use jj_lib::backend::{
    Backend, ChangeId, Commit, CommitId, CopyId, MillisSinceEpoch, Signature, Timestamp, Tree, TreeId,
    TreeValue, make_root_commit,
};
use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
use jj_lib::merge::Merge;
use jj_lib::object_id::ObjectId as _;
use jj_lib::repo_path::{RepoPath, RepoPathComponentBuf};
use jj_lib::settings::UserSettings;
use pollster::FutureExt as _;

fn settings() -> UserSettings {
    let mut config = StackedConfig::with_defaults();
    config.add_layer(
        ConfigLayer::parse(ConfigSource::User, "user.name = \"Ann\"\nuser.email = \"ann@example.com\"\n")
            .unwrap(),
    );
    UserSettings::from_config(config).unwrap()
}

fn backend(dir: &tempfile::TempDir) -> AmberBackend {
    AmberBackend::init(&settings(), dir.path()).unwrap()
}

/// Deterministic incompressible-ish bytes.
fn data(n: usize, seed: u64) -> Vec<u8> {
    let mut x = seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
    (0..n)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

fn write_file(b: &AmberBackend, bytes: &[u8]) -> jj_lib::backend::FileId {
    let mut r = futures::io::Cursor::new(bytes.to_vec());
    b.write_file(RepoPath::root(), &mut r).block_on().unwrap()
}

fn read_file(b: &AmberBackend, id: &jj_lib::backend::FileId) -> Vec<u8> {
    use futures::AsyncReadExt as _;
    let mut r = b.read_file(RepoPath::root(), id).block_on().unwrap();
    let mut out = Vec::new();
    r.read_to_end(&mut out).block_on().unwrap();
    out
}

fn sig(name: &str, ms: i64, tz: i32) -> Signature {
    Signature {
        name: name.into(),
        email: format!("{}@example.com", name.to_lowercase()),
        timestamp: Timestamp { timestamp: MillisSinceEpoch(ms), tz_offset: tz },
    }
}

fn commit(_b: &AmberBackend, parents: Vec<CommitId>, tree: TreeId, msg: &str) -> Commit {
    Commit {
        parents,
        predecessors: vec![],
        root_tree: Merge::resolved(tree),
        conflict_labels: Merge::resolved(String::new()),
        change_id: ChangeId::new((0..CHANGE_ID_LENGTH as u8).collect()),
        description: msg.into(),
        author: sig("Ann", 1_700_000_000_123, 120),
        committer: sig("Bob", 1_700_000_000_456, -300),
        secure_sig: None,
    }
}

fn name(s: &str) -> RepoPathComponentBuf {
    RepoPathComponentBuf::new(s).unwrap()
}

#[test]
fn root_commit_and_empty_tree() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    assert_eq!(b.empty_tree_id().as_bytes(), empty_dir_key().as_bytes());
    assert!(b.read_tree(RepoPath::root(), b.empty_tree_id()).block_on().unwrap().is_empty());
    assert_eq!(b.write_tree(RepoPath::root(), &Tree::default()).block_on().unwrap(), *b.empty_tree_id());
    let root = b.read_commit(b.root_commit_id()).block_on().unwrap();
    assert_eq!(root, make_root_commit(b.root_change_id().clone(), b.empty_tree_id().clone()));
}

#[test]
fn files_round_trip_with_ingest_keys() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let src = tempfile::tempdir().unwrap();
    // Empty, one chunk, and several chunks under a FileNode (chunks are at most 1 MiB).
    let cases = [(0usize, "empty"), (5, "small"), (3 << 20, "big")];
    for (n, file) in cases {
        let bytes = data(n, n as u64 + 1);
        std::fs::write(src.path().join(file), &bytes).unwrap();
        let id = write_file(&b, &bytes);
        assert_eq!(read_file(&b, &id), bytes, "{file}");
    }
    // The same files ingested by core get the same keys.
    let (_, root) = ingest::dir(b.store(), src.path(), ingest::Opts::default());
    let entries = fstree::collect_entries(root.unwrap(), |k| b.store().get(k)).unwrap();
    for e in entries {
        let bytes = std::fs::read(src.path().join(std::str::from_utf8(&e.name).unwrap())).unwrap();
        assert_eq!(write_file(&b, &bytes).as_bytes(), &e.content_key[..]);
    }
    let big = Key::parse(write_file(&b, &data(3 << 20, (3 << 20) + 1)).as_bytes()).unwrap();
    assert_eq!(big.type_(), Type::FileNode);
    assert_eq!(big.length(), 3 << 20);
}

#[test]
fn trees_round_trip() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let file = write_file(&b, b"hello\n");
    let link = b.write_symlink(RepoPath::root(), "../target").block_on().unwrap();
    assert_eq!(b.read_symlink(RepoPath::root(), &link).block_on().unwrap(), "../target");
    let sub = Tree::from_sorted_entries(vec![(
        name("x.sh"),
        TreeValue::File { id: file.clone(), executable: true, copy_id: CopyId::placeholder() },
    )]);
    let sub_id = b.write_tree(RepoPath::root(), &sub).block_on().unwrap();
    let c = commit(&b, vec![b.root_commit_id().clone()], sub_id.clone(), "vendored");
    let (commit_id, _) = b.write_commit(c, None).block_on().unwrap();

    let tree = Tree::from_sorted_entries(vec![
        (name("a.txt"), TreeValue::File { id: file, executable: false, copy_id: CopyId::placeholder() }),
        (name("link"), TreeValue::Symlink(link)),
        (name("sub"), TreeValue::Tree(sub_id)),
        (name("vendor"), TreeValue::GitSubmodule(commit_id)),
    ]);
    let id = b.write_tree(RepoPath::root(), &tree).block_on().unwrap();
    assert_eq!(b.read_tree(RepoPath::root(), &id).block_on().unwrap(), tree);

    // What core sees: plain POSIX entries, the link target inline, and a directory entry holding the
    // commit, which reads as that commit's tree.
    let key = Key::parse(id.as_bytes()).unwrap();
    let entries = fstree::collect_entries(key, |k| b.store().get(k)).unwrap();
    let modes: Vec<(String, u64)> =
        entries.iter().map(|e| (String::from_utf8(e.name.clone()).unwrap(), e.mode)).collect();
    assert_eq!(
        modes,
        [("a.txt", 0o100644), ("link", 0o120777), ("sub", 0o040755), ("vendor", 0o040755)]
            .map(|(n, m)| (n.to_owned(), m))
    );
    assert_eq!(entries[1].link_target, b"../target");
    let through = fstree::resolve_entry(key, "vendor/x.sh", |k| b.store().get(k)).unwrap().unwrap();
    assert_eq!(through.mode, 0o100755);
}

#[test]
fn large_directories_become_dir_nodes() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let file = write_file(&b, b"x");
    let entries: Vec<_> = (0..5000)
        .map(|i| {
            (
                name(&format!("f{i:05}")),
                TreeValue::File { id: file.clone(), executable: false, copy_id: CopyId::placeholder() },
            )
        })
        .collect();
    let tree = Tree::from_sorted_entries(entries);
    let id = b.write_tree(RepoPath::root(), &tree).block_on().unwrap();
    assert_eq!(Key::parse(id.as_bytes()).unwrap().type_(), Type::DirNode);
    assert_eq!(b.read_tree(RepoPath::root(), &id).block_on().unwrap(), tree);
}

#[test]
fn commits_round_trip_as_amber_commits() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let empty = b.empty_tree_id().clone();
    let file = write_file(&b, b"1");
    let t1 = b
        .write_tree(
            RepoPath::root(),
            &Tree::from_sorted_entries(vec![(
                name("f"),
                TreeValue::File { id: file, executable: false, copy_id: CopyId::placeholder() },
            )]),
        )
        .block_on()
        .unwrap();

    let a = commit(&b, vec![b.root_commit_id().clone()], empty.clone(), "a");
    let (a_id, a_stored) = b.write_commit(a.clone(), None).block_on().unwrap();
    assert_eq!(a_stored, a);
    assert_eq!(b.read_commit(&a_id).block_on().unwrap(), a);

    // Only the root as parent: stored as a root commit, which core decodes.
    let a_key = Key::parse(a_id.as_bytes()).unwrap();
    assert_eq!(a_key.type_(), Type::Commit);
    let raw = AmberCommit::decode(&b.store().get(a_key).unwrap()).unwrap();
    assert!(raw.parents.is_empty());
    assert_eq!(raw.change_id, a.change_id.to_bytes());
    assert_eq!(raw.author.when, 1_700_000_000_123_000_000);
    assert_eq!(raw.committer.tz_offset, -300);

    // A conflicted merge with labels.
    let mut m = commit(&b, vec![a_id.clone(), a_id.clone()], empty.clone(), "merge\n");
    m.parents[1] = b
        .write_commit(commit(&b, vec![b.root_commit_id().clone()], t1.clone(), "b"), None)
        .block_on()
        .unwrap()
        .0;
    m.root_tree = Merge::from_vec(vec![t1.clone(), empty.clone(), t1.clone()]);
    m.conflict_labels = Merge::from_vec(vec!["ours".into(), String::new(), "theirs".into()]);
    let (m_id, m_stored) = b.write_commit(m.clone(), None).block_on().unwrap();
    assert_eq!(m_stored, m);
    assert_eq!(b.read_commit(&m_id).block_on().unwrap(), m);
    let raw = AmberCommit::decode(&b.store().get(Key::parse(m_id.as_bytes()).unwrap()).unwrap()).unwrap();
    assert_eq!(raw.conflict_terms.len(), 2);
    assert_eq!(raw.conflict_labels, ["ours", "", "theirs"]);
    // The key's length is the footprint: own bytes plus every tree's length.
    let own = raw.encode().unwrap().len() as u64;
    let trees: u64 = raw.trees().iter().map(|k| k.length()).sum();
    assert_eq!(Key::parse(m_id.as_bytes()).unwrap().length(), own + trees);

    // Unlabelled conflicts store no labels and read back unlabelled.
    let mut u = m.clone();
    u.conflict_labels = Merge::resolved(String::new());
    let (u_id, _) = b.write_commit(u.clone(), None).block_on().unwrap();
    assert_eq!(b.read_commit(&u_id).block_on().unwrap(), u);

    // Predecessors are not stored, and the returned commit says so.
    let mut p = commit(&b, vec![a_id.clone()], empty, "p");
    p.predecessors = vec![a_id.clone()];
    let (p_id, p_stored) = b.write_commit(p, None).block_on().unwrap();
    assert!(p_stored.predecessors.is_empty());
    assert_eq!(b.read_commit(&p_id).block_on().unwrap(), p_stored);
}

#[test]
fn signatures_cover_the_amber_payload() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let c = commit(&b, vec![b.root_commit_id().clone()], b.empty_tree_id().clone(), "signed");
    let mut seen = Vec::new();
    let mut sign = |data: &[u8]| {
        seen = data.to_vec();
        Ok(blake3::hash(data).as_bytes().to_vec())
    };
    let (id, stored) = b.write_commit(c, Some(&mut sign)).block_on().unwrap();
    let sig = stored.secure_sig.clone().expect("signed");
    assert_eq!(sig.data, seen);
    assert_eq!(sig.sig, blake3::hash(&seen).as_bytes().to_vec());
    assert_eq!(b.read_commit(&id).block_on().unwrap(), stored);
    let raw = AmberCommit::decode(&b.store().get(Key::parse(id.as_bytes()).unwrap()).unwrap()).unwrap();
    assert_eq!(raw.signature_payload().unwrap(), seen);
    assert_eq!(raw.signature, sig.sig);
}

#[test]
fn foreign_commits_get_stable_change_ids() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    let id = Identity {
        name: "dstore".into(),
        email: String::new(),
        when: 1_700_000_000_000_000_001,
        tz_offset: 0,
    };
    let mut c = AmberCommit {
        tree: empty_dir_key(),
        parents: vec![],
        author: id.clone(),
        committer: id,
        message: "pushed by dstore".into(),
        signature: vec![],
        public_key: vec![],
        change_id: vec![],
        conflict_terms: vec![],
        conflict_labels: vec![],
    };
    let (k1, raw1) = c.object().unwrap();
    b.store().put(k1, &raw1).unwrap();
    c.change_id = vec![7; 4];
    let (k2, raw2) = c.object().unwrap();
    b.store().put(k2, &raw2).unwrap();

    let read = |k: Key| b.read_commit(&CommitId::new(k.as_bytes().to_vec())).block_on().unwrap();
    let (j1, j2) = (read(k1), read(k2));
    assert_eq!(j1.change_id.as_bytes().len(), CHANGE_ID_LENGTH);
    assert_eq!(j2.change_id.as_bytes().len(), CHANGE_ID_LENGTH);
    assert_ne!(j1.change_id, j2.change_id);
    assert_eq!(read(k1).change_id, j1.change_id);
    assert_eq!(j1.parents, vec![b.root_commit_id().clone()]);
    // Nanoseconds that are not whole milliseconds round down.
    assert_eq!(j1.author.timestamp.timestamp, MillisSinceEpoch(1_700_000_000_000));
}

#[test]
fn unsupported_shapes_are_refused() {
    let dir = tempfile::tempdir().unwrap();
    let b = backend(&dir);
    assert!(b.write_symlink(RepoPath::root(), "").block_on().is_err());
    let (a_id, _) = b
        .write_commit(commit(&b, vec![b.root_commit_id().clone()], b.empty_tree_id().clone(), "a"), None)
        .block_on()
        .unwrap();
    let m = commit(&b, vec![a_id, b.root_commit_id().clone()], b.empty_tree_id().clone(), "m");
    assert!(b.write_commit(m, None).block_on().is_err());
    let bad = CommitId::new(write_file(&b, b"not a commit").to_bytes());
    assert!(b.read_commit(&bad).block_on().is_err());
}

#[test]
fn a_second_process_sees_the_objects() {
    let dir = tempfile::tempdir().unwrap();
    let b = Arc::new(backend(&dir));
    let (id, c) = b
        .write_commit(commit(&b, vec![b.root_commit_id().clone()], b.empty_tree_id().clone(), "a"), None)
        .block_on()
        .unwrap();
    // Another handle on the same directory, as another jj command would open it.
    let other = AmberBackend::load(&settings(), dir.path()).unwrap();
    assert_eq!(other.read_commit(&id).block_on().unwrap(), c);
}

tests/sync.rs:
//! Moving commits and bookmarks through a dstore cluster (dstore-testkit's in-memory fake nodes):
//! the reference operations with their compare-and-swap, and two jj repositories sharing a branch
//! through fetch and push as the CLI does it.

use std::collections::BTreeMap;
use std::sync::Arc;
use std::time::Duration;

use ajj::backend::AmberBackend;
use ajj::bookmarks::{self, PushSelection};
use ajj::dstore::{self, Error};
use amber_store_core::fstree;
use amber_store_core::key::Key;
use amber_store_core::packstore;
use dstore_client::{Cluster, Config as ClientConfig, Ctx};
use dstore_testkit::fake::{FakeCluster, FakeClusterConfig};
use dstore_transport::Endpoint;
use dstore_transport::mem::Network;
use jj_lib::backend::CommitId;
use jj_lib::commit::Commit;
use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
use jj_lib::object_id::ObjectId as _;
use jj_lib::op_store::RefTarget;
use jj_lib::ref_name::{RefName, RefNameBuf, RemoteName};
use jj_lib::repo::{ReadonlyRepo, Repo as _};
use jj_lib::settings::UserSettings;
use jj_lib::signing::Signer;
use jj_lib::workspace::Workspace;

struct Env {
    fc: Arc<FakeCluster>,
    net: Arc<Network>,
}

impl Env {
    async fn start() -> Env {
        let net = Network::new();
        let fc = FakeCluster::start(&net, FakeClusterConfig::default()).await;
        Env { fc, net }
    }

    async fn dial(&self, id: u8) -> Cluster {
        let endpoint: Arc<dyn Endpoint> = self.net.bind(dstore_client::NodeId([id; 32]), &[]);
        Cluster::dial(
            &Ctx::background(),
            ClientConfig {
                endpoint: Some(endpoint),
                ticket: self.fc.ticket(),
                logger: Some(dstore::quiet_logger()),
                request_timeout: Duration::from_secs(20),
                ..ClientConfig::default()
            },
        )
        .await
        .unwrap()
    }
}

fn settings(user: &str) -> UserSettings {
    let mut config = StackedConfig::with_defaults();
    let text = format!("user.name = \"{user}\"\nuser.email = \"{}@example.com\"\n", user.to_lowercase());
    config.add_layer(ConfigLayer::parse(ConfigSource::User, &text).unwrap());
    UserSettings::from_config(config).unwrap()
}

async fn init_repo(dir: &std::path::Path, user: &str) -> Arc<ReadonlyRepo> {
    let s = settings(user);
    let (_, repo) = Workspace::init_with_backend(
        &s,
        dir,
        &|settings, store_path| Ok(Box::new(AmberBackend::init(settings, store_path)?)),
        Signer::from_settings(&s).unwrap(),
    )
    .await
    .unwrap();
    repo
}

fn amber(repo: &ReadonlyRepo) -> &AmberBackend {
    repo.store().backend_impl::<AmberBackend>().unwrap()
}

fn key(id: &CommitId) -> Key {
    Key::parse(id.as_bytes()).unwrap()
}

/// Commits a child of `parent` (the root when `None`) with a new description; returns the repo.
async fn commit_on(
    repo: Arc<ReadonlyRepo>,
    parent: Option<&CommitId>,
    msg: &str,
) -> (Arc<ReadonlyRepo>, Commit) {
    let parent = parent.cloned().unwrap_or_else(|| repo.store().root_commit_id().clone());
    let mut tx = repo.start_transaction();
    let tree = repo.store().get_commit_async(&parent).await.unwrap().tree();
    let c = tx.repo_mut().new_commit(vec![parent], tree).set_description(msg).write().await.unwrap();
    let repo = tx.commit(format!("commit {msg}")).await.unwrap();
    (repo, c)
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn references_move_only_from_the_expected_commit() {
    let env = Env::start().await;
    let cl = env.dial(0xc1).await;
    let dir = tempfile::tempdir().unwrap();
    let repo = init_repo(dir.path(), "Ann").await;
    let (repo, a) = commit_on(repo, None, "a").await;
    let (repo, b) = commit_on(repo, Some(a.id()), "b").await;
    let store = Arc::clone(amber(&repo).store());

    // Create-only, then a compare-and-swap from the right and from a wrong commit.
    dstore::put_branch(&cl, &store, "r/main", key(a.id()), None, "ann", None).await.unwrap();
    let err = dstore::put_branch(&cl, &store, "r/main", key(b.id()), None, "ann", None).await.unwrap_err();
    assert!(matches!(err, Error::Changed { .. }), "{err}");
    dstore::put_branch(&cl, &store, "r/main", key(b.id()), Some(key(a.id())), "ann", None).await.unwrap();
    // Re-pushing what is already there succeeds (an interrupted push that got that far).
    dstore::put_branch(&cl, &store, "r/main", key(b.id()), Some(key(a.id())), "ann", None).await.unwrap();

    // A tree reference under the prefix is not a branch.
    let (_, tree_root) = {
        let src = tempfile::tempdir().unwrap();
        std::fs::write(src.path().join("f"), b"x").unwrap();
        amber_store_core::ingest::dir(&store, src.path(), amber_store_core::ingest::Opts::default())
    };
    let tree_root = tree_root.unwrap();
    cl.push(&Ctx::background(), Arc::clone(&store), tree_root, "r/tree", "ann", Default::default(), None)
        .await
        .unwrap();
    let (branches, other) = dstore::list_branches(&cl, "r/").await.unwrap();
    assert_eq!(branches.len(), 1);
    assert_eq!(branches[0].bookmark, "main");
    assert_eq!(branches[0].key, key(b.id()));
    assert_eq!(other, ["r/tree"]);

    // A fresh store fetches the whole history.
    let fresh_dir = tempfile::tempdir().unwrap();
    let fresh = Arc::new(packstore::Store::open(fresh_dir.path()).unwrap());
    let fetched = dstore::fetch(&cl, &fresh, key(b.id()), None).await.unwrap();
    assert!(fetched.objects > 0 && fetched.bytes > 0);
    let all = fstree::reachable_keys(key(b.id()), |k| store.get(k)).unwrap();
    assert!(fresh.missing(&all).unwrap().is_empty());
    assert!(all.contains(&key(a.id())));

    // Deletion is conditional too.
    let err = dstore::delete_branch(&cl, "r/main", key(a.id())).await.unwrap_err();
    assert!(matches!(err, Error::Changed { .. }), "{err}");
    dstore::delete_branch(&cl, "r/main", key(b.id())).await.unwrap();
    assert!(dstore::list_branches(&cl, "r/").await.unwrap().0.is_empty());

    cl.close();
    env.fc.close().await;
}

async fn fetch_into(
    repo: Arc<ReadonlyRepo>,
    cl: &Cluster,
    prefix: &str,
) -> (Arc<ReadonlyRepo>, bookmarks::ImportStats) {
    let store = Arc::clone(amber(&repo).store());
    let (branches, _) = dstore::list_branches(cl, prefix).await.unwrap();
    let mut fetched = BTreeMap::new();
    for b in branches {
        dstore::fetch(cl, &store, b.key, None).await.unwrap();
        fetched.insert(RefNameBuf::from(b.bookmark.as_str()), CommitId::new(b.key.as_bytes().to_vec()));
    }
    let mut tx = repo.start_transaction();
    let stats = bookmarks::import_remote_branches(tx.repo_mut(), RemoteName::new("origin"), &fetched, true)
        .await
        .unwrap();
    (tx.commit("fetch").await.unwrap(), stats)
}

async fn push_from(
    repo: Arc<ReadonlyRepo>,
    cl: &Cluster,
    prefix: &str,
    sel: &PushSelection,
) -> (Arc<ReadonlyRepo>, Result<(), Error>) {
    let origin = RemoteName::new("origin");
    let (updates, rejected) = bookmarks::plan_push(repo.view(), origin, sel);
    assert!(rejected.is_empty(), "{rejected:?}");
    let store = Arc::clone(amber(&repo).store());
    let mut tx = repo.start_transaction();
    let mut result = Ok(());
    for u in &updates {
        let name = format!("{prefix}{}", u.name.as_str());
        let before = u.diff.before.as_ref().map(key);
        let r = match &u.diff.after {
            Some(a) => dstore::put_branch(cl, &store, &name, key(a), before, "t", None).await.map(|_| ()),
            None => dstore::delete_branch(cl, &name, before.unwrap()).await,
        };
        match r {
            Ok(()) => bookmarks::record_pushed(tx.repo_mut(), origin, u),
            Err(e) => result = Err(e),
        }
    }
    (tx.commit("push").await.unwrap(), result)
}

fn local(repo: &ReadonlyRepo, name: &str) -> RefTarget {
    repo.view().get_local_bookmark(RefName::new(name)).clone()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn two_repos_share_a_branch() {
    let env = Env::start().await;
    let cl = env.dial(0xc1).await;
    let (d1, d2) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    let ann = init_repo(d1.path(), "Ann").await;
    let bob = init_repo(d2.path(), "Bob").await;
    let named = |n: &str| PushSelection { names: vec![n.into()], ..Default::default() };

    // Ann pushes a new bookmark; it needs naming.
    let (ann, a) = commit_on(ann, None, "a").await;
    let mut tx = ann.start_transaction();
    tx.repo_mut().set_local_bookmark_target(RefName::new("main"), RefTarget::normal(a.id().clone()));
    let ann = tx.commit("bookmark").await.unwrap();
    let (updates, _) = bookmarks::plan_push(ann.view(), RemoteName::new("origin"), &PushSelection::default());
    assert!(updates.is_empty(), "an untracked new bookmark is not pushed by default");
    let (ann, r) = push_from(ann, &cl, "p/", &named("main")).await;
    r.unwrap();
    let origin_main =
        ann.view().get_remote_bookmark(RefName::new("main").to_remote_symbol(RemoteName::new("origin")));
    assert!(origin_main.is_tracked());

    // Bob fetches: main@origin and main, and the commit with its change id.
    let (bob, stats) = fetch_into(bob, &cl, "p/").await;
    assert_eq!(stats.changed, vec![(RefNameBuf::from("main"), Some(a.id().clone()))]);
    assert_eq!(local(&bob, "main"), RefTarget::normal(a.id().clone()));
    let bob_a = bob.store().get_commit_async(a.id()).await.unwrap();
    assert_eq!(bob_a.change_id(), a.change_id());
    assert_eq!(bob_a.description(), "a");

    // Bob advances main and pushes by default (it is tracked now).
    let (bob, b) = commit_on(bob, Some(a.id()), "b").await;
    let mut tx = bob.start_transaction();
    tx.repo_mut().set_local_bookmark_target(RefName::new("main"), RefTarget::normal(b.id().clone()));
    let bob = tx.commit("move").await.unwrap();
    let (_bob, r) = push_from(bob, &cl, "p/", &PushSelection::default()).await;
    r.unwrap();

    // Ann, still at a, moves main elsewhere: her push is refused, her fetch conflicts the bookmark.
    let (ann, a2) = commit_on(ann, Some(a.id()), "a2").await;
    let mut tx = ann.start_transaction();
    tx.repo_mut().set_local_bookmark_target(RefName::new("main"), RefTarget::normal(a2.id().clone()));
    let ann = tx.commit("move").await.unwrap();
    let (ann, r) = push_from(ann, &cl, "p/", &PushSelection::default()).await;
    assert!(matches!(r, Err(Error::Changed { .. })));
    let (ann, _) = fetch_into(ann, &cl, "p/").await;
    assert!(local(&ann, "main").has_conflict());

    // Resolving to Bob's commit makes the bookmark match; nothing left to push.
    let mut tx = ann.start_transaction();
    tx.repo_mut().set_local_bookmark_target(RefName::new("main"), RefTarget::normal(b.id().clone()));
    let ann = tx.commit("resolve").await.unwrap();
    let (updates, _) = bookmarks::plan_push(ann.view(), RemoteName::new("origin"), &PushSelection::default());
    assert!(updates.is_empty());

    // Deleting the bookmark and pushing the deletion removes the reference.
    let mut tx = ann.start_transaction();
    tx.repo_mut().set_local_bookmark_target(RefName::new("main"), RefTarget::absent());
    let ann = tx.commit("delete").await.unwrap();
    let (updates, _) = bookmarks::plan_push(ann.view(), RemoteName::new("origin"), &PushSelection::default());
    assert!(updates.is_empty(), "deletions need --deleted");
    let (_ann, r) = push_from(ann, &cl, "p/", &PushSelection { deleted: true, ..Default::default() }).await;
    r.unwrap();
    assert!(dstore::list_branches(&cl, "p/").await.unwrap().0.is_empty());

    cl.close();
    env.fc.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn fetch_abandons_what_the_remote_dropped() {
    let env = Env::start().await;
    let cl = env.dial(0xc1).await;
    let (d1, d2) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    let ann = init_repo(d1.path(), "Ann").await;
    let bob = init_repo(d2.path(), "Bob").await;
    let store = Arc::clone(amber(&ann).store());

    let (ann, a) = commit_on(ann, None, "a").await;
    let (ann, x) = commit_on(ann, Some(a.id()), "x").await;
    dstore::put_branch(&cl, &store, "q/topic", key(x.id()), None, "ann", None).await.unwrap();
    let (bob, _) = fetch_into(bob, &cl, "q/").await;
    assert!(bob.view().heads().contains(x.id()));

    // The topic is rewritten upstream: x is replaced by a sibling.
    let (_, y) = commit_on(ann, Some(a.id()), "y").await;
    dstore::put_branch(&cl, &store, "q/topic", key(y.id()), Some(key(x.id())), "ann", None).await.unwrap();
    let (bob, stats) = fetch_into(bob, &cl, "q/").await;
    assert_eq!(stats.abandoned, vec![x.id().clone()]);
    assert!(!bob.view().heads().contains(x.id()));
    assert!(bob.view().heads().contains(y.id()));

    cl.close();
    env.fc.close().await;
}

